-- One row for one plant. Generated by scripts/build-duplicates-sql.mjs from scripts/plant-merge.sql,
-- scripts/employers-loader.sql and scripts/plant-duplicates.sql: do not edit; change those and build again.
--
-- It adds the plant merge the database keeps (plant_merge, plant_keeps, plants_apart), then cleans up:
-- every outside id (the EPA registry id) carried by more than one live plant is decided in SQL, on the
-- database this runs on. Rows that are certainly one plant are merged; the rest are left for a person,
-- listed in Admin Tools. References to plants that no longer exist are removed. Every decision is a line
-- in load_log (load 'plant-duplicates'; look = true on the ones to read). Safe to run again: a second run
-- finds nothing to merge and writes nothing.

-- ---------------------------------------------------------------------------
-- What stays (scripts/plant-merge.sql)
-- ---------------------------------------------------------------------------

-- One row for one plant: what stays in the database so that a migration, the
-- intake runner and Admin Tools merge two plant rows by one rule.
--
--   plant_keeps(a, b)          which of two rows that are one plant is the one to keep
--   plant_merge_takes(k, g)    the facts the kept row would take from the other
--   plant_merge(keep, gone …)  folds one row into the other and says so in load_log
--   plants_apart               pairs an admin said are two plants
--
-- Additive and safe to run again. scripts/build-duplicates-sql.mjs puts this
-- file into the migration; scripts/ingest/README.md describes it.

-- Two plants an admin looked at and said are two plants: they are not offered
-- as one again, by the cleanup or by the lists in Admin Tools. The lower id
-- is always `a_id`.
CREATE TABLE IF NOT EXISTS plants_apart (
  a_id uuid NOT NULL REFERENCES factories(id) ON DELETE CASCADE,
  b_id uuid NOT NULL REFERENCES factories(id) ON DELETE CASCADE,
  decided_by uuid REFERENCES users(id) ON DELETE SET NULL,
  decided_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (a_id, b_id),
  CHECK (a_id < b_id)
);
CREATE INDEX IF NOT EXISTS plants_apart_b_idx ON plants_apart (b_id);

-- A decision is found by the plant it is about (Admin Tools reads why a pair waits).
CREATE INDEX IF NOT EXISTS load_log_entity_idx ON load_log (entity_id) WHERE entity_id IS NOT NULL;
-- The few staged records an admin said are not some plant, found by that plant.
CREATE INDEX IF NOT EXISTS intake_links_not_ids_idx ON intake_links USING gin (not_ids) WHERE not_ids <> '{}';

-- Of two rows that are one plant, the one to keep: the one written from
-- sources; else the one with a headcount; else the one placed in a county
-- (its coordinates agree with its state); else the one with more facts filled
-- in; else the older; else the lower id. Its name is the name that stays.
CREATE OR REPLACE FUNCTION plant_keeps(p_a uuid, p_b uuid) RETURNS uuid LANGUAGE sql STABLE AS $f$
  SELECT f.id FROM factories f WHERE f.id IN (p_a, p_b)
  ORDER BY f.curated DESC, (f.workforce_size IS NOT NULL) DESC, (f.county_fips IS NOT NULL) DESC,
           ((NULLIF(btrim(f.address), '') IS NOT NULL)::int + (NULLIF(btrim(f.city), '') IS NOT NULL)::int
            + (NULLIF(btrim(f.zip_code), '') IS NOT NULL)::int + (f.primary_naics IS NOT NULL)::int
            + (f.primary_naics_description IS NOT NULL)::int + (NULLIF(btrim(f.products), '') IS NOT NULL)::int
            + (f.opened_year IS NOT NULL)::int) DESC,
           f.created_at, f.id
  LIMIT 1
$f$;

-- The facts the kept row takes from the other, in fact_sources' words: only
-- where its own is empty, and never one an admin emptied on purpose.
CREATE OR REPLACE FUNCTION plant_merge_takes(p_keep uuid, p_gone uuid) RETURNS text[] LANGUAGE sql STABLE AS $f$
  SELECT coalesce(array_agg(t.fact ORDER BY t.ord), '{}')
  FROM factories k, factories g,
       LATERAL (VALUES
         -- A post office box alone is not where a plant is: the other row's street address is taken over it,
         -- unless the kept row was written from sources.
         (1, 'address', NULLIF(btrim(g.address), '') IS NOT NULL AND g.address !~* '^\s*(p\.?\s*o\.?\s*)?box\s+[0-9a-z]+\s*$'
                        AND (NULLIF(btrim(k.address), '') IS NULL OR (NOT k.curated AND k.address ~* '^\s*(p\.?\s*o\.?\s*)?box\s+[0-9a-z]+\s*$'))),
         (2, 'city', NULLIF(btrim(k.city), '') IS NULL AND NULLIF(btrim(g.city), '') IS NOT NULL),
         (3, 'zip', NULLIF(btrim(k.zip_code), '') IS NULL AND NULLIF(btrim(g.zip_code), '') IS NOT NULL),
         -- The industry's name; and its code, where the code belongs to the name the kept row ends up with.
         (4, 'industry', (k.primary_naics_description IS NULL AND g.primary_naics_description IS NOT NULL)
                         OR (k.primary_naics IS NULL AND g.primary_naics IS NOT NULL
                             AND (k.primary_naics_description IS NULL OR g.primary_naics_description IS NULL
                                  OR g.primary_naics_description = k.primary_naics_description))),
         (5, 'headcount', k.workforce_size IS NULL AND g.workforce_size IS NOT NULL),
         (6, 'products', NULLIF(btrim(k.products), '') IS NULL AND NULLIF(btrim(g.products), '') IS NOT NULL),
         (7, 'opened', k.opened_year IS NULL AND g.opened_year IS NOT NULL)
       ) AS t(ord, fact, takes)
  WHERE k.id = p_keep AND g.id = p_gone AND t.takes
    AND NOT EXISTS (SELECT 1 FROM fact_sources s WHERE s.factory_id = k.id AND s.fact = t.fact AND s.source = 'admin')
$f$;

-- Folds plant `p_gone` into plant `p_keep`. The kept row keeps its name, its
-- company, its place and every fact it has, and takes the other's where its
-- own are empty (plant_merge_takes). It is curated if either was. Where each
-- fact came from follows the fact (fact_sources; a fact taken that had no
-- origin on record is marked 'merged', at the rank it had where it was).
--
-- Everything attached moves: jobs (which then belong to the kept plant's
-- company), careers recorded at the plant, citations, every outside id (the
-- kept plant then holds an id the two shared once, and that row is no longer
-- marked `duplicate`), staged records resolved to the plant and matches
-- waiting on it, and what an admin said the plant is not. Requests to add a
-- plant name a company and a place, never a plant row: there is nothing of
-- theirs to move.
--
-- It writes record_merges, so record_now('factory', <old id>) leads to the
-- kept plant, and one line in load_log: the row kept, why (`p_why`), what was
-- taken and what moved. Returns the same as jsonb.
--
--   p_via   who merged: 'admin', 'cleanup' (a migration, named in p_load) or 'run'
--   p_load  the load the log line is filed under
-- Refused (nothing changes): a plant into itself (PM400), a row that is not
-- there (PM404), and a plant written from sources into one that was not
-- (PM409): that merge is made the other way round.
CREATE OR REPLACE FUNCTION plant_merge(
  p_keep uuid, p_gone uuid, p_via text DEFAULT 'admin', p_actor uuid DEFAULT NULL, p_load text DEFAULT 'plant-merge',
  p_why text DEFAULT NULL, p_look boolean DEFAULT false, p_run bigint DEFAULT NULL, p_evidence jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql AS $f$
DECLARE
  k factories%ROWTYPE;
  g factories%ROWTYPE;
  v_takes text[];
  v_fact text;
  v_metres integer;
  v_jobs integer := 0;
  v_careers integer := 0;
  v_citations integer := 0;
  v_ids integer := 0;
  v_shared integer := 0;
  v_records integer := 0;
  v_moved jsonb;
  v_said text[] := '{}';
  v_company text;
  v_gone_company text;
BEGIN
  IF p_keep IS NULL OR p_gone IS NULL OR p_keep = p_gone THEN
    RAISE EXCEPTION USING ERRCODE = 'PM400', MESSAGE = 'Choose a different plant to merge into.';
  END IF;
  -- Both rows are held, in one order, so two merges cannot cross.
  PERFORM 1 FROM factories WHERE id IN (p_keep, p_gone) ORDER BY id FOR UPDATE;
  SELECT * INTO k FROM factories WHERE id = p_keep;
  SELECT * INTO g FROM factories WHERE id = p_gone;
  IF g.id IS NULL THEN RAISE EXCEPTION USING ERRCODE = 'PM404', MESSAGE = 'Plant not found'; END IF;
  IF k.id IS NULL THEN RAISE EXCEPTION USING ERRCODE = 'PM404', MESSAGE = 'The plant to merge into was not found.'; END IF;
  IF g.curated AND NOT k.curated THEN
    RAISE EXCEPTION USING ERRCODE = 'PM409',
      MESSAGE = format('%s was written from sources and %s was not: keep %s and merge the other into it.', g.name, k.name, g.name);
  END IF;

  v_takes := plant_merge_takes(p_keep, p_gone);
  v_metres := CASE WHEN k.lat IS NOT NULL AND k.lng IS NOT NULL AND g.lat IS NOT NULL AND g.lng IS NOT NULL
    THEN round(sqrt(power((k.lat - g.lat) * 111320, 2) + power((k.lng - g.lng) * 111320 * cos(radians(k.lat)), 2)))::integer END;
  SELECT name INTO v_company FROM companies WHERE id = k.company_id;
  SELECT name INTO v_gone_company FROM companies WHERE id = g.company_id;

  -- Where each fact taken came from goes with it.
  FOREACH v_fact IN ARRAY v_takes LOOP
    DELETE FROM fact_sources WHERE factory_id = p_keep AND fact = v_fact;
    UPDATE fact_sources SET factory_id = p_keep WHERE factory_id = p_gone AND fact = v_fact;
    IF NOT FOUND THEN
      INSERT INTO fact_sources (factory_id, fact, source, rank, as_of, set_by)
        VALUES (p_keep, v_fact, 'merged', CASE WHEN g.curated THEN 80 ELSE 10 END,
                CASE WHEN v_fact = 'headcount' AND g.workforce_year IS NOT NULL THEN make_date(g.workforce_year, 12, 31) END, p_actor);
    END IF;
    -- A run that set the fact on the row that is going can still take it back from the row that has it now.
    UPDATE intake_changes SET entity_id = p_keep WHERE entity_id = p_gone AND op = 'fact' AND fact = v_fact AND undone_at IS NULL;
  END LOOP;

  -- Jobs: at the kept plant, for the kept plant's company.
  UPDATE jobs SET factory_id = p_keep, company_id = COALESCE(k.company_id, company_id), updated_at = now() WHERE factory_id = p_gone;
  GET DIAGNOSTICS v_jobs = ROW_COUNT;
  -- Careers recorded at the plant: the kept row's own line stands where both have one.
  UPDATE factory_occupations x SET factory_id = p_keep WHERE x.factory_id = p_gone
    AND NOT EXISTS (SELECT 1 FROM factory_occupations y WHERE y.factory_id = p_keep AND y.occupation_id = x.occupation_id);
  GET DIAGNOSTICS v_careers = ROW_COUNT;

  -- Citations: one per source address.
  DELETE FROM external_references x WHERE x.entity_type = 'factories' AND x.entity_id = p_gone AND x.source = 'CURATED'
    AND EXISTS (SELECT 1 FROM external_references y WHERE y.entity_type = 'factories' AND y.entity_id = p_keep AND y.source = 'CURATED' AND y.url = x.url);
  UPDATE external_references SET entity_id = p_keep WHERE entity_type = 'factories' AND entity_id = p_gone AND source = 'CURATED';
  GET DIAGNOSTICS v_citations = ROW_COUNT;

  -- Outside ids. One the two rows shared is kept once, on the kept row; the rest move.
  DELETE FROM external_references x WHERE x.entity_type = 'factories' AND x.entity_id = p_gone AND x.source <> 'CURATED'
    AND EXISTS (SELECT 1 FROM external_references y WHERE y.entity_type = 'factories' AND y.entity_id = p_keep
                AND y.source = x.source AND y.external_id = x.external_id);
  GET DIAGNOSTICS v_shared = ROW_COUNT;
  UPDATE external_references SET entity_id = p_keep WHERE entity_type = 'factories' AND entity_id = p_gone AND source <> 'CURATED';
  GET DIAGNOSTICS v_ids = ROW_COUNT;
  -- A row left behind by a plant that no longer exists gives the id up, and an id only this plant now carries is no duplicate.
  DELETE FROM external_references y USING external_references x
    WHERE x.entity_type = 'factories' AND x.entity_id = p_keep AND x.source <> 'CURATED' AND x.duplicate
      AND y.entity_type = 'factories' AND y.source = x.source AND y.external_id = x.external_id AND y.id <> x.id
      AND NOT EXISTS (SELECT 1 FROM factories f WHERE f.id = y.entity_id);
  UPDATE external_references x SET duplicate = false
    WHERE x.entity_type = 'factories' AND x.entity_id = p_keep AND x.source <> 'CURATED' AND x.duplicate
      AND NOT EXISTS (SELECT 1 FROM external_references y WHERE y.entity_type = 'factories' AND y.source = x.source
                      AND y.external_id = x.external_id AND y.id <> x.id AND NOT y.duplicate);

  -- Intake: staged records resolved to the plant, matches waiting on it, and what an admin said it is not.
  UPDATE intake_links SET entity_id = p_keep WHERE entity_id = p_gone;
  GET DIAGNOSTICS v_records = ROW_COUNT;
  UPDATE intake_links SET not_ids = (SELECT coalesce(array_agg(DISTINCT CASE WHEN x = p_gone THEN p_keep ELSE x END), '{}') FROM unnest(not_ids) x)
    WHERE not_ids <> '{}' AND not_ids @> ARRAY[p_gone];
  UPDATE intake_review SET entity_id = p_keep WHERE entity_id = p_gone;
  UPDATE intake_review q SET candidates = (
      SELECT coalesce(jsonb_agg(c ORDER BY ord), '[]'::jsonb) FROM (
        SELECT DISTINCT ON (c->>'id') c, ord FROM (
          SELECT CASE WHEN e->>'id' = p_gone::text THEN e || jsonb_build_object('id', p_keep::text) ELSE e END AS c, ord
          FROM jsonb_array_elements(q.candidates) WITH ORDINALITY t(e, ord)) s
        ORDER BY c->>'id', ord) d)
    WHERE q.status = 'waiting' AND q.candidates @> jsonb_build_array(jsonb_build_object('id', p_gone::text));
  -- The old review list (migration 0009): the kept row's own line stands.
  UPDATE factory_review x SET factory_id = p_keep WHERE x.factory_id = p_gone
    AND NOT EXISTS (SELECT 1 FROM factory_review y WHERE y.factory_id = p_keep);
  -- What was said to be a different plant from the one going is a different plant from the one kept.
  INSERT INTO plants_apart (a_id, b_id, decided_by, decided_at)
    SELECT least(p_keep, o.other), greatest(p_keep, o.other), o.decided_by, o.decided_at
    FROM (SELECT CASE WHEN a_id = p_gone THEN b_id ELSE a_id END AS other, decided_by, decided_at
          FROM plants_apart WHERE a_id = p_gone OR b_id = p_gone) o
    WHERE o.other <> p_keep
  ON CONFLICT (a_id, b_id) DO NOTHING;

  -- The history: an id that pointed at the row that is going leads to the one kept.
  INSERT INTO record_merges (kind, from_id, into_id, from_name, via, run_id, actor_id, note)
    VALUES ('factory', p_gone, p_keep, g.name, p_via, p_run, p_actor, CASE WHEN p_via = 'admin' THEN NULL ELSE p_load END)
  ON CONFLICT (kind, from_id) DO NOTHING;

  DELETE FROM factories WHERE id = p_gone;

  UPDATE factories x SET
    address = CASE WHEN 'address' = ANY (v_takes) THEN g.address ELSE x.address END,
    city = CASE WHEN 'city' = ANY (v_takes) THEN g.city ELSE x.city END,
    zip_code = CASE WHEN 'zip' = ANY (v_takes) THEN g.zip_code ELSE x.zip_code END,
    primary_naics_description = CASE WHEN 'industry' = ANY (v_takes) THEN COALESCE(x.primary_naics_description, g.primary_naics_description) ELSE x.primary_naics_description END,
    primary_naics = CASE WHEN 'industry' = ANY (v_takes)
      THEN COALESCE(x.primary_naics, CASE WHEN g.primary_naics_description IS NULL
                                           OR g.primary_naics_description = COALESCE(x.primary_naics_description, g.primary_naics_description)
                                          THEN g.primary_naics END)
      ELSE x.primary_naics END,
    workforce_size = CASE WHEN 'headcount' = ANY (v_takes) THEN g.workforce_size ELSE x.workforce_size END,
    workforce_year = CASE WHEN 'headcount' = ANY (v_takes) THEN g.workforce_year ELSE x.workforce_year END,
    workforce_source = CASE WHEN 'headcount' = ANY (v_takes) THEN g.workforce_source ELSE x.workforce_source END,
    workforce_note = CASE WHEN 'headcount' = ANY (v_takes) THEN g.workforce_note ELSE x.workforce_note END,
    products = CASE WHEN 'products' = ANY (v_takes) THEN g.products ELSE x.products END,
    opened_year = CASE WHEN 'opened' = ANY (v_takes) THEN g.opened_year ELSE x.opened_year END,
    -- Not facts a source fills, and shown nowhere today: kept where the kept row has none.
    specialization = COALESCE(NULLIF(btrim(x.specialization), ''), g.specialization),
    description = COALESCE(NULLIF(btrim(x.description), ''), g.description),
    curated = x.curated OR g.curated,
    updated_at = now()
  WHERE x.id = p_keep;

  v_moved := jsonb_strip_nulls(jsonb_build_object(
    'jobs', NULLIF(v_jobs, 0), 'careers', NULLIF(v_careers, 0), 'citations', NULLIF(v_citations, 0),
    'ids', NULLIF(v_ids, 0), 'sharedIds', NULLIF(v_shared, 0), 'records', NULLIF(v_records, 0)));
  IF cardinality(v_takes) > 0 THEN v_said := v_said || ('Taken from it: ' || array_to_string(v_takes, ', ')); END IF;
  IF v_jobs > 0 THEN v_said := v_said || format('%s job%s moved', v_jobs, CASE WHEN v_jobs = 1 THEN '' ELSE 's' END); END IF;
  IF v_careers > 0 THEN v_said := v_said || format('%s career%s moved', v_careers, CASE WHEN v_careers = 1 THEN '' ELSE 's' END); END IF;
  IF v_citations > 0 THEN v_said := v_said || format('%s citation%s moved', v_citations, CASE WHEN v_citations = 1 THEN '' ELSE 's' END); END IF;
  IF v_ids > 0 THEN v_said := v_said || format('%s outside id%s moved', v_ids, CASE WHEN v_ids = 1 THEN '' ELSE 's' END); END IF;
  IF v_shared > 0 THEN v_said := v_said || format('%s shared id%s kept once', v_shared, CASE WHEN v_shared = 1 THEN '' ELSE 's' END); END IF;

  INSERT INTO load_log (load, kind, action, look, company, plant, detail, metres, run_id, entity_id, evidence)
    VALUES (p_load, 'plant', 'merged', p_look, v_company, k.name,
            format('kept, and "%s"%s merged into it%s. %s', g.name,
                   CASE WHEN g.company_id IS DISTINCT FROM k.company_id THEN format(' (filed under "%s")', coalesce(v_gone_company, 'no company')) ELSE '' END,
                   coalesce(': ' || p_why, ''),
                   CASE WHEN cardinality(v_said) > 0 THEN array_to_string(v_said, '; ') || '.' ELSE 'Nothing was taken from it.' END),
            v_metres, p_run, p_keep,
            coalesce(p_evidence, '{}'::jsonb) || jsonb_build_object(
              'merged', p_gone, 'mergedName', g.name, 'mergedCompany', v_gone_company, 'took', to_jsonb(v_takes), 'moved', v_moved));

  RETURN jsonb_build_object(
    'kept', jsonb_build_object('id', p_keep, 'name', k.name),
    'merged', jsonb_build_object('id', p_gone, 'name', g.name),
    'took', to_jsonb(v_takes), 'moved', v_moved, 'metres', v_metres);
END $f$;

-- ---------------------------------------------------------------------------
-- The employer loader's functions (scripts/employers-loader.sql): this session only
-- ---------------------------------------------------------------------------

-- The employer loader: the functions every migration generated by
-- scripts/build-employers-sql.mjs carries. They live in pg_temp (this session
-- only) and are replaced when defined again, so a migration can run twice on
-- one connection or once each on two.
--
-- The loader cannot see the database it will run on, so every decision is
-- made here, at apply time, and written to load_log as it is made:
--   company  found | created | merged | renamed | set aside | alias not used | parent | similar
--   plant    matched | moved | inserted | swept | not loaded
-- `look` marks the lines a person should read.

CREATE OR REPLACE FUNCTION pg_temp.el_log(p_kind text, p_action text, p_look boolean, p_company text, p_plant text, p_detail text, p_metres integer DEFAULT NULL)
RETURNS void LANGUAGE sql AS $f$
  INSERT INTO load_log (load, kind, action, look, company, plant, detail, metres)
  VALUES (current_setting('el.load'), p_kind, p_action, p_look, p_company, p_plant, p_detail, p_metres)
$f$;

-- A name for comparing: lower case, "&" as "and", everything else that is not
-- a letter or digit as one space.
CREATE OR REPLACE FUNCTION pg_temp.el_norm(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $f$
  SELECT btrim(regexp_replace(lower(replace(coalesce(t, ''), '&', ' and ')), '[^a-z0-9]+', ' ', 'g'))
$f$;

-- Metres between two points. About 111 km per degree of latitude; longitude shrinks with the cosine.
CREATE OR REPLACE FUNCTION pg_temp.el_metres(lat1 float8, lng1 float8, lat2 float8, lng2 float8) RETURNS integer LANGUAGE sql IMMUTABLE AS $f$
  SELECT round(sqrt(power((lat1 - lat2) * 111320, 2) + power((lng1 - lng2) * 111320 * cos(radians(lat1)), 2)))::integer
$f$;

-- A plant's name without the legal endings, for telling that two names are one ("GLOBITECH INC" is "GlobiTech").
CREATE OR REPLACE FUNCTION pg_temp.el_bare(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $f$
  SELECT btrim(regexp_replace(regexp_replace(' ' || replace(pg_temp.el_norm(t), ' ', '  ') || ' ',
    ' (the|inc|incorporated|llc|corp|corporation|co|company|lp|ltd|plc) ', ' ', 'g'), ' +', ' ', 'g'))
$f$;

-- The fuller of two texts: the one that is there, else the longer, else the later in byte order.
-- Symmetric, so two files that both describe a record leave the same text whichever loads first.
CREATE OR REPLACE FUNCTION pg_temp.el_fuller(a text, b text) RETURNS text LANGUAGE sql IMMUTABLE AS $f$
  SELECT CASE
    WHEN NULLIF(btrim(a), '') IS NULL THEN NULLIF(btrim(b), '')
    WHEN NULLIF(btrim(b), '') IS NULL THEN btrim(a)
    WHEN (length(btrim(a)), btrim(a) COLLATE "C") >= (length(btrim(b)), btrim(b) COLLATE "C") THEN btrim(a)
    ELSE btrim(b) END
$f$;

-- The words of a plant's name that tell it from its company's other plants:
-- without the company's own words, the place, and words every plant has.
CREATE OR REPLACE FUNCTION pg_temp.el_words(name text, drop_words text[]) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$
  SELECT coalesce(array_agg(DISTINCT w), '{}')
  FROM regexp_split_to_table(pg_temp.el_norm(name), ' ') w
  WHERE w <> '' AND w <> ALL (drop_words)
    AND w <> ALL (ARRAY['plant', 'plants', 'facility', 'facilities', 'site', 'complex', 'works', 'factory', 'manufacturing', 'mfg',
      'operations', 'operation', 'campus', 'center', 'centre', 'division', 'div', 'inc', 'llc', 'corp', 'corporation', 'co', 'company',
      'lp', 'ltd', 'usa', 'us', 'u', 's', 'america', 'american', 'the', 'of', 'and', 'at', 'a', 'part', 'dba', 'group', 'holdings'])
$f$;

-- Whether two sets of telling words share one ("giga" and "gigafactory" count as shared).
CREATE OR REPLACE FUNCTION pg_temp.el_share(a text[], b text[]) RETURNS boolean LANGUAGE sql IMMUTABLE AS $f$
  SELECT EXISTS (
    SELECT 1 FROM unnest(a) x, unnest(b) y
    WHERE x = y OR (length(x) >= 4 AND length(y) >= 4 AND (left(y, length(x)) = x OR left(x, length(y)) = y)))
$f$;

-- Whether a name contains one of the keys as whole words ("bell helicopter" in "BELL HELICOPTER TEXTRON PLANT 5").
CREATE OR REPLACE FUNCTION pg_temp.el_refers(name text, keys text[]) RETURNS boolean LANGUAGE sql IMMUTABLE AS $f$
  SELECT EXISTS (SELECT 1 FROM unnest(keys) k WHERE position(' ' || k || ' ' IN ' ' || pg_temp.el_norm(name) || ' ') > 0)
$f$;

-- One company into another, by id: everything that pointed at `m` points at
-- `k`, `k` takes whatever profile it lacks and remembers the name. The row
-- moves follow merge_company in scripts/build-cleanup-sql.mjs and
-- mergeRecords in server/lib/records.ts.
CREATE OR REPLACE FUNCTION pg_temp.el_merge_company(k uuid, m uuid) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE o companies%ROWTYPE;
BEGIN
  SELECT * INTO o FROM companies WHERE id = m;
  IF o.id IS NULL OR k IS NULL OR k = m THEN RETURN; END IF;
  UPDATE factories SET company_id = k WHERE company_id = m;
  UPDATE jobs SET company_id = k WHERE company_id = m;
  UPDATE invites SET company_id = k WHERE company_id = m;
  -- A person with a row at both keeps the stronger one (access over a request).
  UPDATE company_members y SET status = 'active', decided_at = x.decided_at, decided_by = x.decided_by
    FROM company_members x
    WHERE x.company_id = m AND y.company_id = k AND y.user_id = x.user_id AND x.status = 'active' AND y.status <> 'active';
  UPDATE company_members x SET company_id = k WHERE company_id = m
    AND NOT EXISTS (SELECT 1 FROM company_members y WHERE y.company_id = k AND y.user_id = x.user_id);
  UPDATE company_requests SET company_id = k WHERE company_id = m;
  UPDATE company_requests SET added_company_id = k WHERE added_company_id = m;
  UPDATE companies SET parent_company_id = k WHERE parent_company_id = m AND id <> k;
  UPDATE company_state_headcounts x SET company_id = k WHERE company_id = m
    AND NOT EXISTS (SELECT 1 FROM company_state_headcounts y WHERE y.company_id = k AND y.state = x.state);
  DELETE FROM external_references x WHERE x.entity_type = 'companies' AND x.entity_id = m AND x.source = 'CURATED'
    AND EXISTS (SELECT 1 FROM external_references y WHERE y.entity_type = 'companies' AND y.entity_id = k AND y.source = 'CURATED' AND y.url = x.url);
  UPDATE external_references SET entity_id = k WHERE entity_type = 'companies' AND entity_id = m;
  -- The merge is remembered (record_merges, migration 0043), so an id that pointed at the row that is going still
  -- leads to the one kept. A copy of the database from before that migration has no such table and is left without.
  IF to_regclass('public.record_merges') IS NOT NULL THEN
    INSERT INTO record_merges (kind, from_id, into_id, from_name, via, note)
      VALUES ('company', m, k, o.name, 'loader', current_setting('el.load', true))
    ON CONFLICT (kind, from_id) DO NOTHING;
  END IF;
  -- The slug is unique: the row that is going gives it up before the kept row can take it.
  DELETE FROM companies WHERE id = m;
  UPDATE companies c SET
    domain = COALESCE(c.domain, o.domain),
    description = COALESCE(NULLIF(btrim(c.description), ''), o.description),
    industry = CASE WHEN c.industry IS NULL OR lower(btrim(c.industry)) IN ('', 'manufacturing') THEN COALESCE(o.industry, c.industry) ELSE c.industry END,
    featured = c.featured OR o.featured,
    slug = COALESCE(c.slug, o.slug),
    parent_company_id = COALESCE(c.parent_company_id, NULLIF(o.parent_company_id, k)),
    headquarters_lat = COALESCE(c.headquarters_lat, o.headquarters_lat),
    headquarters_lng = COALESCE(c.headquarters_lng, o.headquarters_lng),
    headquarters_city = CASE WHEN c.headquarters_city IS NULL THEN o.headquarters_city ELSE c.headquarters_city END,
    headquarters_state = CASE WHEN c.headquarters_city IS NULL THEN o.headquarters_state ELSE c.headquarters_state END,
    headquarters_country = CASE WHEN c.headquarters_city IS NULL THEN o.headquarters_country ELSE c.headquarters_country END,
    aliases = (SELECT array_agg(DISTINCT a) FROM unnest(COALESCE(c.aliases, '{}') || COALESCE(o.aliases, '{}') || ARRAY[o.name]) AS a WHERE lower(a) <> lower(c.name)),
    updated_at = now()
  WHERE c.id = k;
END $f$;

-- Finds the company a file names, merging the rows it is found under, or
-- creates it; then sets its profile. Returns its id.
--
-- Found means an exact name, in any letter case: the company's name or one of
-- its alsoKnownAs, against a row's name or a row's aliases. Never a partial or
-- similar name. `protect` holds the names of the other companies and parents
-- in the research files: one of those is never taken as another name for this
-- company, whatever the file says.
CREATE OR REPLACE FUNCTION pg_temp.el_company(c jsonb, protect text[], hints boolean) RETURNS uuid LANGUAGE plpgsql AS $f$
DECLARE
  v_name text := btrim(c->>'name');
  v_akas text[];      -- alsoKnownAs as written, without protected names
  v_names text[];     -- every name to look under, lower case
  v_states text[];    -- the states this file has its plants in
  v_found uuid[];
  v_unused text;
  v_guard text[] := array_remove(protect, lower(btrim(c->>'name')));
  r record;
  k uuid;
  v_kept text;
  v_parent uuid;
  v_pname text := NULLIF(btrim(coalesce(c->>'parent', '')), '');
  v_pvia text;
  v_slug text;
  v_similar text;
  h jsonb;
BEGIN
  SELECT coalesce(array_agg(a ORDER BY ord) FILTER (WHERE lower(a) <> ALL (v_guard)), '{}'),
         string_agg(a, '; ' ORDER BY ord) FILTER (WHERE lower(a) = ANY (v_guard))
    INTO v_akas, v_unused
  FROM (SELECT DISTINCT ON (lower(btrim(a))) btrim(a) AS a, ord
        FROM jsonb_array_elements_text(coalesce(c->'alsoKnownAs', '[]'::jsonb)) WITH ORDINALITY t(a, ord)
        WHERE btrim(a) <> '' AND lower(btrim(a)) <> lower(v_name)
        ORDER BY lower(btrim(a)), ord) s;
  IF v_unused IS NOT NULL THEN
    PERFORM pg_temp.el_log('company', 'alias not used', true, v_name, NULL,
      'listed as another name but is a company of its own in the research: ' || v_unused);
  END IF;
  SELECT array_agg(lower(a)) INTO v_names FROM unnest(ARRAY[v_name] || v_akas) a;
  SELECT coalesce(array_agg(DISTINCT p->>'state'), '{}') INTO v_states FROM jsonb_array_elements(coalesce(c->'plants', '[]'::jsonb)) p;

  -- A different company that happens to have one of these names, as the file
  -- points it out: it takes the name the file gives it and stands aside. It is
  -- known by one of its plants, so once it has moved this does nothing.
  FOR r IN SELECT x->>'name' AS name, x->>'withPlant' AS plant, x->>'renameTo' AS new_name
           FROM jsonb_array_elements(coalesce(c->'setAside', '[]'::jsonb)) x LOOP
    UPDATE companies co SET name = r.new_name, updated_at = now()
      WHERE lower(co.name) = lower(r.name)
        AND EXISTS (SELECT 1 FROM factories f WHERE f.company_id = co.id AND lower(f.name) = lower(r.plant))
        AND NOT EXISTS (SELECT 1 FROM companies o WHERE lower(o.name) = lower(r.new_name));
    IF FOUND THEN
      PERFORM pg_temp.el_log('company', 'set aside', true, v_name, NULL,
        format('"%s" with the plant "%s" is a different company and is now "%s"', r.name, r.plant, r.new_name));
    END IF;
  END LOOP;

  -- The rows it is found under, first; then each is read.
  SELECT coalesce(array_agg(co.id), '{}') INTO v_found FROM companies co
    WHERE lower(co.name) = ANY (v_names) OR EXISTS (SELECT 1 FROM unnest(co.aliases) a WHERE lower(a) = ANY (v_names));
  FOR r IN
    SELECT co.id, co.name, lower(co.name) = ANY (v_names) AS by_name,
           (SELECT count(*) FROM factories f WHERE f.company_id = co.id) AS plants,
           (SELECT string_agg(s, ', ' ORDER BY s) FROM (SELECT DISTINCT f.state AS s FROM factories f WHERE f.company_id = co.id) d) AS states,
           (SELECT string_agg(format('%s (%s, %s)', f.name, coalesce(f.city, '?'), coalesce(f.state, '?')), '; ')
              FROM (SELECT * FROM factories f WHERE f.company_id = co.id ORDER BY f.state, f.name LIMIT 3) f) AS sample,
           -- Nothing ties the row to this company but its name: no plant in a state the file's plants are in, not the same web domain.
           cardinality(v_states) > 0 AND EXISTS (SELECT 1 FROM factories f WHERE f.company_id = co.id)
             AND NOT EXISTS (SELECT 1 FROM factories f WHERE f.company_id = co.id AND f.state = ANY (v_states))
             AND co.domain IS DISTINCT FROM NULLIF(c->>'domain', '') AS name_only,
           (SELECT string_agg(a, '; ') FROM unnest(co.aliases) a WHERE lower(a) = ANY (v_names)) AS via
    FROM companies co
    WHERE co.id = ANY (v_found)
    -- The row that is kept: the one already named as the file names it, then one known by that name, then the one with
    -- a profile, people or the most plants.
    ORDER BY (lower(co.name) = lower(v_name)) DESC, EXISTS (SELECT 1 FROM unnest(co.aliases) a WHERE lower(a) = lower(v_name)) DESC,
             co.featured DESC, (co.slug IS NOT NULL) DESC,
             (SELECT count(*) FROM company_members m WHERE m.company_id = co.id) DESC, 4 DESC, co.created_at, co.id
  LOOP
    IF NOT r.by_name AND lower(r.name) = ANY (v_guard) THEN
      PERFORM pg_temp.el_log('company', 'alias not used', true, v_name, NULL,
        format('"%s" is also known as "%s" but is a company of its own in the research: left alone', r.name, r.via));
      CONTINUE;
    END IF;
    IF k IS NULL THEN
      k := r.id;
      v_kept := r.name;
      PERFORM pg_temp.el_log('company', 'found', r.name_only, v_name, NULL,
        format('as "%s"%s, %s plant%s%s%s', r.name, CASE WHEN r.by_name THEN '' ELSE ' (by its other name "' || r.via || '")' END,
               r.plants, CASE WHEN r.plants = 1 THEN '' ELSE 's' END,
               CASE WHEN r.plants BETWEEN 1 AND 3 OR r.name_only THEN ': ' || r.sample || CASE WHEN r.plants > 3 THEN '; ...' ELSE '' END ELSE '' END,
               CASE WHEN r.name_only THEN '. None is in a state this file has it in: the same company?' ELSE '' END));
    ELSE
      PERFORM pg_temp.el_merge_company(k, r.id);
      PERFORM pg_temp.el_log('company', 'merged', true, v_name, NULL,
        format('"%s" (%s plant%s%s%s%s) into "%s"', r.name, r.plants, CASE WHEN r.plants = 1 THEN '' ELSE 's' END,
               CASE WHEN r.states IS NULL THEN '' ELSE ' in ' || r.states END,
               CASE WHEN r.plants BETWEEN 1 AND 3 THEN ': ' || r.sample ELSE '' END,
               CASE WHEN r.by_name THEN '' ELSE ', found by its other name "' || r.via || '"' END, v_kept));
    END IF;
  END LOOP;

  IF k IS NULL THEN
    INSERT INTO companies (name) VALUES (v_name) RETURNING id INTO k;
    v_kept := v_name;
    PERFORM pg_temp.el_log('company', 'created', false, v_name, NULL, NULL);
  ELSIF v_kept <> v_name THEN
    PERFORM pg_temp.el_log('company', 'renamed', false, v_name, NULL, format('"%s" is now "%s"', v_kept, v_name));
  END IF;

  -- The parent: by exact name, then by another name it is known by, then by
  -- its name without a legal ending ("PACCAR Inc." for "PACCAR") when exactly
  -- one company answers to that. Created bare when there is none.
  IF v_pname IS NOT NULL AND lower(v_pname) <> lower(v_name) THEN
    SELECT id INTO v_parent FROM companies WHERE lower(name) = lower(v_pname) AND id <> k ORDER BY featured DESC, created_at, id LIMIT 1;
    IF v_parent IS NULL THEN
      SELECT min(id::text)::uuid, 'its other name' INTO v_parent, v_pvia FROM companies co
        WHERE co.id <> k AND EXISTS (SELECT 1 FROM unnest(co.aliases) a WHERE lower(a) = lower(v_pname)) HAVING count(*) = 1;
    END IF;
    IF v_parent IS NULL THEN
      SELECT min(id::text)::uuid, 'its name without the legal ending' INTO v_parent, v_pvia FROM companies co
        WHERE co.id <> k AND btrim(regexp_replace(' ' || pg_temp.el_norm(co.name) || ' ', ' (the|inc|incorporated|corp|corporation|co|company|llc|ltd|lp|plc|holdings|group) ', ' ', 'g'))
            = pg_temp.el_norm(v_pname)
        HAVING count(*) = 1;
    END IF;
    IF v_parent IS NULL THEN
      INSERT INTO companies (name) VALUES (v_pname) RETURNING id INTO v_parent;
      PERFORM pg_temp.el_log('company', 'parent', false, v_name, NULL, format('"%s" was not there and was created, with no plants', v_pname));
    ELSIF v_pvia IS NOT NULL THEN
      PERFORM pg_temp.el_log('company', 'parent', true, v_name, NULL,
        format('"%s" found by %s: "%s"', v_pname, v_pvia, (SELECT name FROM companies WHERE id = v_parent)));
    END IF;
    -- Never a loop: a company is not the parent of its own parent.
    IF EXISTS (SELECT 1 FROM companies WHERE id = v_parent AND parent_company_id = k) THEN
      PERFORM pg_temp.el_log('company', 'parent', true, v_name, NULL, format('"%s" is recorded as part of this company: parent not set', v_pname));
      v_parent := NULL;
    END IF;
  END IF;

  v_slug := trim(both '-' from regexp_replace(
    regexp_replace(lower(v_name), '\m(company|corporation|corp|incorporated|inc|llc|ltd|co)\M\.?', '', 'g'), '[^a-z0-9]+', '-', 'g'));
  h := c->'headquarters';

  UPDATE companies co SET
    name = v_name,
    -- Other names: what it had, the name it gives up, then the file's, 30 at most, in alphabetical order.
    aliases = (SELECT array_agg(a ORDER BY lower(a) COLLATE "C", a COLLATE "C") FROM (
                 SELECT DISTINCT ON (lower(a)) a, ord FROM unnest(
                   COALESCE(co.aliases, '{}') || CASE WHEN lower(co.name) <> lower(v_name) THEN ARRAY[co.name] ELSE '{}'::text[] END || v_akas
                 ) WITH ORDINALITY u(a, ord)
                 WHERE lower(a) <> lower(v_name) ORDER BY lower(a), ord) s WHERE ord <= 30 OR ord IS NULL),
    domain = COALESCE(co.domain, NULLIF(c->>'domain', '')),
    industry = COALESCE(pg_temp.el_fuller(CASE WHEN lower(btrim(co.industry)) IN ('', 'manufacturing') THEN NULL ELSE co.industry END, c->>'industry'), co.industry),
    description = pg_temp.el_fuller(co.description, c->>'description'),
    headquarters_city = CASE WHEN co.headquarters_city IS NULL THEN NULLIF(h->>'city', '') ELSE co.headquarters_city END,
    headquarters_state = CASE WHEN co.headquarters_city IS NULL THEN NULLIF(h->>'state', '') ELSE co.headquarters_state END,
    headquarters_country = CASE WHEN co.headquarters_city IS NULL THEN NULLIF(h->>'country', '') ELSE co.headquarters_country END,
    parent_company_id = COALESCE(v_parent, co.parent_company_id),
    -- A featured employer has a profile: a company the file only names (no web domain, no description) is loaded
    -- and left as it is.
    featured = co.featured OR COALESCE(co.domain, NULLIF(c->>'domain', '')) IS NOT NULL
               OR pg_temp.el_fuller(co.description, c->>'description') IS NOT NULL,
    slug = COALESCE(co.slug, CASE WHEN v_slug <> '' AND COALESCE(co.domain, NULLIF(c->>'domain', '')) IS NOT NULL
                                   AND NOT EXISTS (SELECT 1 FROM companies o WHERE o.slug = v_slug) THEN v_slug END),
    updated_at = now()
  WHERE co.id = k;

  -- People in a state: the newer figure wins, then the larger.
  INSERT INTO company_state_headcounts (company_id, state, people, year, source, note)
    SELECT k, upper(e->>'state'), (e->>'count')::integer, (e->>'year')::smallint, NULLIF(e->>'source', ''), NULLIF(e->>'note', '')
    FROM jsonb_array_elements(coalesce(c->'people', '[]'::jsonb)) e
    WHERE e->>'count' IS NOT NULL AND e->>'state' IS NOT NULL
  ON CONFLICT (company_id, state) DO UPDATE
    SET people = EXCLUDED.people, year = EXCLUDED.year, source = EXCLUDED.source, note = EXCLUDED.note
    WHERE (COALESCE(EXCLUDED.year, 0), EXCLUDED.people, COALESCE(EXCLUDED.source, '') COLLATE "C", COALESCE(EXCLUDED.note, '') COLLATE "C")
        > (COALESCE(company_state_headcounts.year, 0), company_state_headcounts.people, COALESCE(company_state_headcounts.source, '') COLLATE "C", COALESCE(company_state_headcounts.note, '') COLLATE "C");

  INSERT INTO external_references (entity_type, entity_id, source, external_id, url)
    SELECT DISTINCT 'companies'::entity_type, k, 'CURATED', current_setting('el.load'), u
    FROM jsonb_array_elements_text(coalesce(c->'sources', '[]'::jsonb)) u WHERE btrim(u) <> ''
  ON CONFLICT (entity_type, entity_id, url) WHERE source = 'CURATED' DO NOTHING;

  -- For the person rehearsing: companies left alone whose name contains this
  -- one's name or one of its other names, or that share its web domain. A
  -- name that belongs in alsoKnownAs shows up here; so does a namesake.
  IF hints THEN
    SELECT string_agg(format('%s (%s)', name, plants), '; ' ORDER BY plants DESC, name) INTO v_similar FROM (
      SELECT DISTINCT co.name, (SELECT count(*) FROM factories f WHERE f.company_id = co.id) AS plants
      FROM unnest(ARRAY[v_name] || v_akas) key
      JOIN companies co ON co.name ILIKE '%' || replace(replace(key, '%', ''), '_', '') || '%'
      WHERE co.id <> k AND lower(co.name) <> ALL (v_guard)
        AND (length(pg_temp.el_norm(key)) >= 5 OR key = v_name) AND length(pg_temp.el_norm(key)) >= 3
        AND position(' ' || pg_temp.el_norm(key) || ' ' IN ' ' || pg_temp.el_norm(co.name) || ' ') > 0
      ORDER BY 2 DESC, 1 LIMIT 12) s;
    IF v_similar IS NOT NULL THEN
      PERFORM pg_temp.el_log('company', 'similar', true, v_name, NULL, 'not merged, name contains one of its names: ' || v_similar);
    END IF;
    SELECT string_agg(format('%s (%s)', co.name, (SELECT count(*) FROM factories f WHERE f.company_id = co.id)), '; ' ORDER BY co.name) INTO v_similar
      FROM companies co WHERE co.id <> k AND co.domain = NULLIF(c->>'domain', '') AND lower(co.name) <> ALL (v_guard);
    IF v_similar IS NOT NULL THEN
      PERFORM pg_temp.el_log('company', 'similar', true, v_name, NULL, 'not merged, same web domain: ' || v_similar);
    END IF;
  END IF;
  RETURN k;
END $f$;

-- Writes one research plant onto a factory row. The first time a row is
-- curated the file's facts replace what the row had. After that (the same
-- plant in a second file, or the same file again) each fact keeps the fuller
-- of the two: a value over none, the newer headcount, the longer text. Those
-- rules are symmetric, so the order files load in does not change the result.
CREATE OR REPLACE FUNCTION pg_temp.el_apply(fid uuid, move_to uuid, p jsonb) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  f factories%ROWTYPE;
  v_first boolean;
  v_sub text := p->>'subsector';
  v_code3 text;
  v_naics text;
  v_head boolean;
BEGIN
  SELECT * INTO f FROM factories WHERE id = fid;
  v_first := NOT f.curated;
  IF NOT v_first THEN v_sub := pg_temp.el_fuller(f.primary_naics_description, v_sub); END IF;
  v_code3 := ('{"Food Manufacturing":"311","Beverage and Tobacco Product Manufacturing":"312","Textile Mills":"313","Textile Product Mills":"314",
    "Apparel Manufacturing":"315","Leather and Allied Product Manufacturing":"316","Wood Product Manufacturing":"321","Paper Manufacturing":"322",
    "Printing and Related Support Activities":"323","Petroleum and Coal Products Manufacturing":"324","Chemical Manufacturing":"325",
    "Plastics and Rubber Products Manufacturing":"326","Nonmetallic Mineral Product Manufacturing":"327","Primary Metal Manufacturing":"331",
    "Fabricated Metal Product Manufacturing":"332","Machinery Manufacturing":"333","Computer and Electronic Product Manufacturing":"334",
    "Electrical Equipment, Appliance, and Component Manufacturing":"335","Transportation Equipment Manufacturing":"336",
    "Furniture and Related Product Manufacturing":"337","Miscellaneous Manufacturing":"339"}'::jsonb)->>v_sub;
  -- The industry code: the file's six digits, else the subsector's three, so
  -- the plant always counts in its state's industry mix.
  v_naics := COALESCE(NULLIF(p->>'naics', ''), v_code3);
  IF NOT v_first THEN v_naics := pg_temp.el_fuller(f.primary_naics, v_naics); END IF;
  IF v_code3 IS NOT NULL AND left(COALESCE(v_naics, ''), 3) <> v_code3 THEN v_naics := v_code3; END IF;
  -- The file's headcount replaces the row's when the row is bare, or when it
  -- is the newer figure (then the larger).
  v_head := p->>'employees' IS NOT NULL AND (
    v_first OR f.workforce_size IS NULL
    OR (COALESCE((p->>'employeesYear')::integer, 0), (p->>'employees')::integer, COALESCE(p->>'employeesSource', '') COLLATE "C", COALESCE(p->>'employeesNote', '') COLLATE "C")
     > (COALESCE(f.workforce_year::integer, 0), f.workforce_size, COALESCE(f.workforce_source, '') COLLATE "C", COALESCE(f.workforce_note, '') COLLATE "C"));

  UPDATE factories x SET
    company_id = COALESCE(move_to, x.company_id),
    name = CASE WHEN v_first THEN p->>'name' ELSE pg_temp.el_fuller(x.name, p->>'name') END,
    address = CASE WHEN v_first THEN NULLIF(p->>'address', '') ELSE pg_temp.el_fuller(x.address, p->>'address') END,
    city = CASE WHEN v_first THEN COALESCE(NULLIF(p->>'city', ''), x.city) ELSE pg_temp.el_fuller(x.city, p->>'city') END,
    state = CASE WHEN v_first THEN p->>'state' ELSE x.state END,
    zip_code = left(CASE WHEN v_first THEN NULLIF(p->>'zip', '') ELSE pg_temp.el_fuller(x.zip_code, p->>'zip') END, 10),
    -- Where two files place one plant a little apart, the more northerly (then easterly) point is kept: any fixed rule would do.
    latitude = CASE WHEN v_first OR ((p->>'latitude')::float8, (p->>'longitude')::float8) > (x.latitude::float8, x.longitude::float8) THEN p->>'latitude' ELSE x.latitude END,
    longitude = CASE WHEN v_first OR ((p->>'latitude')::float8, (p->>'longitude')::float8) > (x.latitude::float8, x.longitude::float8) THEN p->>'longitude' ELSE x.longitude END,
    primary_naics_description = v_sub,
    primary_naics = left(v_naics, 6),
    products = CASE WHEN v_first THEN NULLIF(p->>'products', '') ELSE pg_temp.el_fuller(x.products, p->>'products') END,
    workforce_size = CASE WHEN v_head THEN (p->>'employees')::integer ELSE x.workforce_size END,
    workforce_year = CASE WHEN v_head THEN (p->>'employeesYear')::smallint ELSE x.workforce_year END,
    workforce_source = CASE WHEN v_head THEN NULLIF(p->>'employeesSource', '') ELSE x.workforce_source END,
    workforce_note = CASE WHEN v_head THEN NULLIF(p->>'employeesNote', '') ELSE x.workforce_note END,
    -- When two files give a year, production started in the earlier one.
    opened_year = CASE WHEN v_first THEN (p->>'opened')::smallint
                       ELSE LEAST(x.opened_year, (p->>'opened')::smallint) END,
    -- A plant any file calls operating is operating.
    status = CASE WHEN v_first THEN COALESCE(p->>'status', 'operating')
                  WHEN x.status = 'operating' OR p->>'status' = 'operating' THEN 'operating' ELSE x.status END,
    curated = true,
    updated_at = now()
  WHERE x.id = fid;

  INSERT INTO external_references (entity_type, entity_id, source, external_id, url)
    SELECT DISTINCT 'factories'::entity_type, fid, 'CURATED', current_setting('el.load'), u
    FROM (SELECT jsonb_array_elements_text(coalesce(p->'sources', '[]'::jsonb)) AS u
          UNION ALL SELECT p->>'employeesSource') s
    WHERE btrim(coalesce(u, '')) <> ''
  ON CONFLICT (entity_type, entity_id, url) WHERE source = 'CURATED' DO NOTHING;

  UPDATE el_pos SET lat = n.latitude::float8, lng = n.longitude::float8 FROM factories n WHERE n.id = fid AND el_pos.id = fid;
END $f$;

-- The plants filed under a company's parent whose names begin with one of the
-- company's own names are the company's ("BELL HELICOPTER TEXTRON PLANT 5"
-- under Textron is Bell's; "MAZDA TOYOTA MANUFACTURING" is not Toyota
-- Manufacturing's). They move to it.
CREATE OR REPLACE FUNCTION pg_temp.el_sweep(k uuid, protect text[]) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  v_name text;
  v_par uuid;
  v_keys text[];
  v_swept integer;
  v_sample text;
BEGIN
  SELECT name, parent_company_id INTO v_name, v_par FROM companies WHERE id = k;
  IF v_par IS NULL THEN RETURN; END IF;
  SELECT coalesce(array_agg(DISTINCT n), '{}') INTO v_keys
  FROM (SELECT pg_temp.el_norm(a) AS n FROM unnest(ARRAY[v_name] || coalesce((SELECT aliases FROM companies WHERE id = k), '{}')) a) s
  WHERE length(n) >= 3 AND n NOT IN (SELECT pg_temp.el_norm(x) FROM unnest(array_remove(protect, lower(v_name))) x);
  IF cardinality(v_keys) = 0 THEN RETURN; END IF;
  WITH moved AS (
    UPDATE factories f SET company_id = k, updated_at = now()
    WHERE f.company_id = v_par
      AND EXISTS (SELECT 1 FROM unnest(v_keys) key WHERE left(pg_temp.el_norm(f.name) || ' ', length(key) + 1) = key || ' ')
    RETURNING f.name, f.state)
  SELECT count(*), string_agg(format('%s (%s)', name, state), '; ' ORDER BY state, name) INTO v_swept, v_sample FROM moved;
  IF v_swept > 0 THEN
    PERFORM pg_temp.el_log('plant', 'swept', true, v_name, NULL,
      format('%s more plant%s named for it moved from its parent "%s": %s', v_swept, CASE WHEN v_swept = 1 THEN '' ELSE 's' END,
             (SELECT name FROM companies WHERE id = v_par), v_sample));
  END IF;
END $f$;

-- Places a company's plants: each onto the existing row that is that plant,
-- or as a new row.
--
-- Candidates, best first:
--   named        the existing plant the corrections name for it (sameAs, its
--                exact name), within 25 km, whoever it is filed under
--   same name    a plant of this company (or its parent, or a company that is
--                part of it) with the same name, within 5 km
--   shared word  one whose name shares a telling word ("Giga", "Refinery"),
--                within 3 km
--   near         any other plant of this company within 1.5 km; an already
--                curated plant only when its name does not say it is a
--                different unit of the same site
--   beside       a plant of any other company within 250 m whose name names
--                this company or this site
-- A plant the corrections mark as new (isNew) takes only a row that already
-- has its name: the row it was given by an earlier load.
--   only one     when the research has one plant of the company in a city:
--                a bare plant of the company in that city within 3.5 km (a
--                large site, placed apart by two sources)
-- A row is taken by one plant per file. A plant found under the parent, or
-- under an unrelated company, moves to this company; one found under a
-- company that is part of this one, under another company the research
-- names, or already curated elsewhere, is updated where it is.
CREATE OR REPLACE FUNCTION pg_temp.el_plants(k uuid, c jsonb, protect text[], states jsonb) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  v_name text := btrim(c->>'name');
  v_par uuid;
  v_family uuid[];
  v_keys text[];      -- this company's names, normalised, three characters or more
  v_bare text[];      -- those names without legal endings
  v_drop text[];      -- the words of the company's name
  r record;
  q record;
  v_fid uuid;
  v_move uuid;
  v_near text;
  v_d integer;
  v_own text;
  v_more integer;
BEGIN
  SELECT parent_company_id INTO v_par FROM companies WHERE id = k;
  -- This company, its parent, and the companies that are part of it.
  SELECT array_agg(id) INTO v_family FROM (
    SELECT k AS id UNION SELECT v_par WHERE v_par IS NOT NULL UNION SELECT id FROM companies WHERE parent_company_id = k) s;
  SELECT coalesce(array_agg(DISTINCT n), '{}') INTO v_keys
  FROM (SELECT pg_temp.el_norm(a) AS n FROM unnest(ARRAY[v_name] || coalesce((SELECT aliases FROM companies WHERE id = k), '{}')) a) s
  WHERE length(n) >= 3 AND n NOT IN (SELECT pg_temp.el_norm(x) FROM unnest(array_remove(protect, lower(v_name))) x);
  SELECT coalesce(array_agg(DISTINCT pg_temp.el_bare(key)), '{}') INTO v_bare FROM unnest(v_keys) key;
  -- Only the name's own words are set aside when plant names are compared, so two files that describe the company
  -- under different lists of other names read a plant's name the same way.
  SELECT coalesce(array_agg(DISTINCT w), '{}') INTO v_drop FROM regexp_split_to_table(pg_temp.el_norm(v_name), ' ') w WHERE w <> '';

  TRUNCATE el_p;
  INSERT INTO el_p (i, p, lat, lng, nname, drop_words)
    SELECT ord::integer, p, (p->>'latitude')::float8, (p->>'longitude')::float8, pg_temp.el_bare(p->>'name'),
           v_drop || regexp_split_to_array(pg_temp.el_norm(coalesce(p->>'city', '') || ' ' || coalesce(p->>'state', '') || ' ' || coalesce(states->>(p->>'state'), '')), ' ')
    FROM jsonb_array_elements(coalesce(c->'plants', '[]'::jsonb)) WITH ORDINALITY t(p, ord);
  UPDATE el_p SET words = pg_temp.el_words(p->>'name', drop_words);

  FOR r IN
    SELECT *, CASE WHEN same_as THEN -1 WHEN usual THEN class ELSE 4 END AS rank FROM (
      SELECT *,
             CASE
               WHEN rel IN (0, 1) THEN d <= CASE class WHEN 0 THEN 5000 WHEN 1 THEN 3000 ELSE 1500 END AND NOT (class = 3 AND curated)
               WHEN rel = 2 THEN (class = 0 AND d <= 5000) OR (class = 1 AND d <= 1500) OR (refers AND d <= CASE class WHEN 1 THEN 3000 ELSE 1500 END)
               ELSE d <= 250 AND (class = 0 OR names_us OR same_site)
             END AS usual
      FROM (
        SELECT b.*,
               CASE WHEN pg_temp.el_bare(b.fname) = b.nname THEN 0
                    WHEN pg_temp.el_share(b.words, fw.words) THEN 1
                    WHEN cardinality(b.words) = 0 OR cardinality(fw.words) = 0 THEN 2
                    ELSE 3 END AS class,
               pg_temp.el_refers(b.fname, v_keys) AS refers,
               -- A stranger's plant names this company when its name carries one of this company's names and does not
               -- spell out a longer name of the company it is filed under ("CHEVRON PHILLIPS CHEMICAL ..." filed under
               -- Chevron is Chevron Phillips Chemical's; the reverse is not Chevron's), or when that company is this one
               -- but for a legal ending.
               coalesce((SELECT max(length(key)) FROM unnest(v_keys) key WHERE position(' ' || key || ' ' IN ' ' || pg_temp.el_norm(b.fname) || ' ') > 0), 0)
                 > CASE WHEN position(' ' || pg_temp.el_bare(b.cname) || ' ' IN ' ' || pg_temp.el_norm(b.fname) || ' ') > 0 THEN length(pg_temp.el_bare(b.cname)) ELSE 0 END
                 OR pg_temp.el_bare(b.cname) = ANY (v_bare) AS names_us,
               cardinality(b.words) >= 2 AND b.words <@ fw.words AS same_site,
               b.alone AND pg_temp.el_norm(b.fcity) = pg_temp.el_norm(b.city) AS alone_in_city
        FROM (
          -- Only rows that could be the plant are read: anyone's within 250 m, this company's and its family's within
          -- 10 km, and the one the corrections name.
          SELECT p.i, p.nname, p.words, p.drop_words, p.p->>'city' AS city, coalesce((p.p->>'alone')::boolean, false) AS alone,
                 coalesce((p.p->>'isNew')::boolean, false) AS is_new,
                 f.id, f.name AS fname, f.city AS fcity, f.curated, f.company_id, oc.name AS cname,
                 CASE WHEN f.company_id = k THEN 0 WHEN oc.parent_company_id = k THEN 1 WHEN f.company_id = v_par THEN 2 ELSE 3 END AS rel,
                 pg_temp.el_metres(p.lat, p.lng, x.lat, x.lng) AS d,
                 coalesce(f.name = p.p->>'sameAs', false) AS same_as
          FROM el_p p
          CROSS JOIN LATERAL (
            SELECT x.id FROM el_pos x
              WHERE x.lat BETWEEN p.lat - 0.003 AND p.lat + 0.003 AND x.lng BETWEEN p.lng - 0.004 AND p.lng + 0.004
            UNION
            SELECT f2.id FROM factories f2 WHERE f2.company_id = ANY (v_family)
            UNION
            SELECT f3.id FROM factories f3 WHERE f3.name = p.p->>'sameAs'
          ) near
          JOIN el_pos x ON x.id = near.id
          JOIN factories f ON f.id = near.id
          LEFT JOIN companies oc ON oc.id = f.company_id
          WHERE pg_temp.el_metres(p.lat, p.lng, x.lat, x.lng) <= CASE WHEN f.name = p.p->>'sameAs' THEN 25000 ELSE 10000 END
          OFFSET 0
        ) b
        CROSS JOIN LATERAL (SELECT pg_temp.el_words(b.fname, b.drop_words) AS words) fw
      ) s
    ) t
    WHERE CASE WHEN is_new THEN usual AND class = 0 AND rel IN (0, 1) ELSE
            same_as OR usual
            -- The company's only plant in the city, in the research and (as far as 3.5 km) in the data: one site, placed apart.
            OR (rel IN (0, 1) AND NOT curated AND alone_in_city AND d <= 3500)
          END
    ORDER BY rank, rel, d, id
  LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM el_p WHERE i = r.i AND fid IS NOT NULL) OR EXISTS (SELECT 1 FROM el_claimed WHERE id = r.id);
    UPDATE el_p SET fid = r.id WHERE i = r.i;
    INSERT INTO el_claimed VALUES (r.id);
    SELECT p INTO q FROM el_p WHERE i = r.i;
    -- Moves to this company: from the parent, or from an unrelated company the research does not name, when the row is bare.
    -- but not from another company the research names, unless the plant's own name says whose it is.
    v_move := CASE WHEN r.rel = 2 THEN k
                   WHEN r.rel = 3 AND NOT r.curated AND (r.same_as OR r.names_us OR lower(coalesce(r.cname, '')) <> ALL (protect)) THEN k END;
    SELECT count(*) INTO v_more FROM el_pos x JOIN factories f ON f.id = x.id
      WHERE f.company_id = k AND f.id <> r.id AND NOT f.curated
        AND x.lat BETWEEN (q.p->>'latitude')::float8 - 0.02 AND (q.p->>'latitude')::float8 + 0.02
        AND pg_temp.el_metres((q.p->>'latitude')::float8, (q.p->>'longitude')::float8, x.lat, x.lng) <= 1500
        AND NOT EXISTS (SELECT 1 FROM el_claimed cl WHERE cl.id = f.id);
    PERFORM pg_temp.el_apply(r.id, v_move, q.p);
    PERFORM pg_temp.el_log('plant',
      CASE WHEN v_move IS NOT NULL AND r.rel <> 0 THEN 'moved' ELSE 'matched' END,
      -- Worth a look: a move, a row left with another company, a curated plant under another name, or an unrelated name far off.
      r.rel <> 0 OR (r.curated AND r.class <> 0) OR (r.class = 3 AND NOT r.refers AND r.d > 500) OR r.d > 1500 OR r.rank = 4,
      v_name, q.p->>'name',
      format('%s "%s"%s at %s m%s%s',
        CASE WHEN r.rank = -1 THEN 'named in the corrections:' WHEN r.rank = 4 THEN 'its only plant in the city:'
             WHEN r.class = 0 THEN 'same name:' WHEN r.class = 1 THEN 'shared word:' WHEN r.class = 2 OR r.refers THEN 'near:' ELSE 'near, unrelated name:' END,
        r.fname,
        CASE WHEN r.rel = 0 THEN ''
             WHEN v_move IS NOT NULL THEN format(', moved from "%s"', r.cname)
             ELSE format(', left with "%s"', r.cname) END,
        r.d,
        CASE WHEN r.curated THEN ', already curated' ELSE '' END,
        CASE WHEN v_more > 0 THEN format('; %s more bare plant%s of this company within 1.5 km', v_more, CASE WHEN v_more = 1 THEN '' ELSE 's' END) ELSE '' END),
      r.d);
  END LOOP;

  -- The rest are new.
  FOR q IN SELECT * FROM el_p WHERE fid IS NULL ORDER BY i LOOP
    INSERT INTO factories (company_id, name, latitude, longitude, state)
      VALUES (k, q.p->>'name', q.p->>'latitude', q.p->>'longitude', q.p->>'state') RETURNING id INTO v_fid;
    INSERT INTO el_pos VALUES (v_fid, q.lat, q.lng);
    INSERT INTO el_claimed VALUES (v_fid);
    PERFORM pg_temp.el_apply(v_fid, NULL, q.p);
    SELECT format('"%s" (%s) at %s m', f.name, coalesce(oc.name, 'no company'), s.d), s.d INTO v_near, v_d
      FROM (SELECT x.id, pg_temp.el_metres(q.lat, q.lng, x.lat, x.lng) AS d FROM el_pos x
            WHERE x.id <> v_fid AND x.lat BETWEEN q.lat - 0.05 AND q.lat + 0.05 AND x.lng BETWEEN q.lng - 0.08 AND q.lng + 0.08
            ORDER BY 2 LIMIT 1) s
      JOIN factories f ON f.id = s.id LEFT JOIN companies oc ON oc.id = f.company_id;
    SELECT format('; this company''s nearest: "%s" at %s m', f.name, s.d) INTO v_own
      FROM (SELECT x.id, pg_temp.el_metres(q.lat, q.lng, x.lat, x.lng) AS d FROM el_pos x JOIN factories f2 ON f2.id = x.id
            WHERE x.id <> v_fid AND f2.company_id IN (k, v_par) AND x.lat BETWEEN q.lat - 0.1 AND q.lat + 0.1 AND x.lng BETWEEN q.lng - 0.15 AND q.lng + 0.15
            ORDER BY 2 LIMIT 1) s
      JOIN factories f ON f.id = s.id;
    PERFORM pg_temp.el_log('plant', 'inserted',
      -- Worth a look: nothing within 2 km (a new site, or a wrong coordinate), something within 250 m (a plant under a name the file did not list), or one of this company's within 10 km.
      v_near IS NULL OR v_d > 2000 OR v_d <= 250 OR v_own IS NOT NULL,
      v_name, q.p->>'name',
      coalesce('nearest plant: ' || v_near, 'no plant within 5 km') || coalesce(v_own, ''), NULL);
    v_near := NULL; v_d := NULL; v_own := NULL;
  END LOOP;

  FOR q IN SELECT s FROM jsonb_array_elements_text(coalesce(c->'notLoaded', '[]'::jsonb)) s LOOP
    PERFORM pg_temp.el_log('plant', 'not loaded', false, v_name, q.s, NULL);
  END LOOP;

  PERFORM pg_temp.el_sweep(k, protect);
END $f$;

-- Loads everything: `data` is what scripts/build-employers-sql.mjs wrote.
CREATE OR REPLACE FUNCTION pg_temp.el_load(data jsonb) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  file jsonb;
  c jsonb;
  k uuid;
  v_protect text[];
  v_touched uuid[] := '{}';
BEGIN
  -- "Table does not exist, skipping" is not news.
  PERFORM set_config('client_min_messages', 'warning', true);
  -- The statements here are long and their tables small: compiling them (JIT) costs far more than running them.
  PERFORM set_config('jit', 'off', true);
  SELECT coalesce(array_agg(lower(x)), '{}') INTO v_protect FROM jsonb_array_elements_text(coalesce(data->'protect', '[]'::jsonb)) x;
  -- Where every plant is, as numbers (coordinates are stored as text; only well-formed ones are read).
  DROP TABLE IF EXISTS el_pos;
  CREATE TEMP TABLE el_pos ON COMMIT DROP AS
    SELECT id, latitude::float8 AS lat, longitude::float8 AS lng FROM factories
    WHERE latitude ~ '^-?[0-9]+([.][0-9]+)?$' AND longitude ~ '^-?[0-9]+([.][0-9]+)?$';
  CREATE INDEX ON el_pos (lat);
  CREATE INDEX ON el_pos (id);
  ANALYZE el_pos;
  DROP TABLE IF EXISTS el_claimed;
  CREATE TEMP TABLE el_claimed (id uuid PRIMARY KEY) ON COMMIT DROP;
  -- The plants of the company being placed: its row in the file, where it is, its name for comparing, the words to
  -- ignore in a name, the words that tell it apart, and the row it was placed on.
  DROP TABLE IF EXISTS el_p;
  CREATE TEMP TABLE el_p (i integer, p jsonb, lat float8, lng float8, nname text, drop_words text[], words text[], fid uuid) ON COMMIT DROP;

  FOR file IN SELECT f FROM jsonb_array_elements(data->'files') f LOOP
    PERFORM set_config('el.load', file->>'brief', true);
    -- A row is taken by one plant per file; the next file may add to it.
    TRUNCATE el_claimed;
    FOR c IN SELECT x FROM jsonb_array_elements(file->'companies') x LOOP
      k := pg_temp.el_company(c, v_protect, coalesce((data->>'hints')::boolean, false));
      v_touched := v_touched || k;
      PERFORM pg_temp.el_plants(k, c, v_protect, coalesce(data->'states', '{}'::jsonb));
    END LOOP;
  END LOOP;
  -- Once every company is as the files leave it: a company merged into a parent late may have brought plants that
  -- are one of its companies'. Each company loaded here, and each company that is part of one, takes its own.
  PERFORM set_config('el.load', (data->'files'->-1)->>'brief', true);
  FOR k IN SELECT co.id FROM companies co
           WHERE co.parent_company_id IS NOT NULL AND (co.id = ANY (v_touched) OR co.parent_company_id = ANY (v_touched))
           ORDER BY co.name LOOP
    PERFORM pg_temp.el_sweep(k, v_protect);
  END LOOP;
  DROP TABLE el_p;
  DROP TABLE el_claimed;
  DROP TABLE el_pos;
END $f$;

-- What this transaction's load decided, to read: a summary for each file,
-- then the lines marked for a look (every line when `everything`).
CREATE OR REPLACE FUNCTION pg_temp.el_report(everything boolean) RETURNS SETOF text LANGUAGE sql AS $f$
  WITH l AS (SELECT * FROM load_log WHERE run_at = now()),
  loads AS (SELECT load, min(id) AS first FROM l GROUP BY load),
  summary AS (
    SELECT lo.first AS ord, 0 AS sub, format(
      '%s: %s companies (%s found, %s created, %s rows merged in, %s renamed); %s plants (%s matched, %s moved, %s inserted, %s swept from a parent; %s not loaded)',
      lo.load,
      count(*) FILTER (WHERE kind = 'company' AND action IN ('found', 'created')),
      count(*) FILTER (WHERE kind = 'company' AND action = 'found'),
      count(*) FILTER (WHERE kind = 'company' AND action = 'created'),
      count(*) FILTER (WHERE kind = 'company' AND action = 'merged'),
      count(*) FILTER (WHERE kind = 'company' AND action = 'renamed'),
      count(*) FILTER (WHERE kind = 'plant' AND action IN ('matched', 'moved', 'inserted')),
      count(*) FILTER (WHERE kind = 'plant' AND action = 'matched'),
      count(*) FILTER (WHERE kind = 'plant' AND action = 'moved'),
      count(*) FILTER (WHERE kind = 'plant' AND action = 'inserted'),
      coalesce(sum((substring(detail FROM '^[0-9]+'))::integer) FILTER (WHERE kind = 'plant' AND action = 'swept'), 0),
      count(*) FILTER (WHERE kind = 'plant' AND action = 'not loaded')) AS line
    FROM l JOIN loads lo ON lo.load = l.load GROUP BY lo.load, lo.first
    UNION ALL
    SELECT lo.first, 1, format(
      '  matched or moved at: under 100 m %s, 100 to 250 m %s, 250 to 500 m %s, 500 m to 1 km %s, 1 to 1.5 km %s, over 1.5 km %s (median %s m, furthest %s m)',
      count(*) FILTER (WHERE metres < 100), count(*) FILTER (WHERE metres >= 100 AND metres < 250),
      count(*) FILTER (WHERE metres >= 250 AND metres < 500), count(*) FILTER (WHERE metres >= 500 AND metres < 1000),
      count(*) FILTER (WHERE metres >= 1000 AND metres <= 1500), count(*) FILTER (WHERE metres > 1500),
      round(percentile_cont(0.5) WITHIN GROUP (ORDER BY metres)), max(metres))
    FROM l JOIN loads lo ON lo.load = l.load WHERE l.metres IS NOT NULL GROUP BY lo.load, lo.first
    UNION ALL
    SELECT lo.first, 2, '  created: ' || string_agg(l.company, '; ' ORDER BY l.id)
    FROM l JOIN loads lo ON lo.load = l.load WHERE l.kind = 'company' AND l.action = 'created' GROUP BY lo.load, lo.first
    UNION ALL
    SELECT lo.first, 3, '  renamed: ' || string_agg(l.detail, '; ' ORDER BY l.id)
    FROM l JOIN loads lo ON lo.load = l.load WHERE l.kind = 'company' AND l.action = 'renamed' GROUP BY lo.load, lo.first
  ),
  lines AS (
    SELECT ord, sub, line FROM summary
    UNION ALL
    SELECT l.id, 9, format('%s%s %s | %s%s%s', CASE WHEN l.look THEN '' ELSE '  ' END, l.kind, l.action, l.company,
                           coalesce(' / ' || l.plant, ''), coalesce(' | ' || l.detail, ''))
    FROM l WHERE (l.look OR everything) AND l.action NOT IN ('renamed', 'merged')
    UNION ALL
    -- The rows merged into one company, on one line.
    SELECT min(l.id), 9, format('company merged | %s | %s', l.company, string_agg(regexp_replace(l.detail, ' into "[^"]*"$', ''), '; ' ORDER BY l.id))
    FROM l WHERE l.action = 'merged' GROUP BY l.load, l.company
  )
  SELECT line FROM lines ORDER BY (sub < 9) DESC, ord, sub
$f$;

-- A rehearsal: does the whole load, reads what it decided, then undoes it.
-- The work is done inside a block that ends by raising an error, which takes
-- every change back; the report rides out in the error. Nothing is left
-- behind whether the caller commits or rolls back. `schema_sql`, when given,
-- is run first inside the same block (a copy of production that does not have
-- the new columns yet).
CREATE OR REPLACE FUNCTION pg_temp.el_rehearse(data jsonb, schema_sql text, everything boolean) RETURNS SETOF text LANGUAGE plpgsql AS $f$
DECLARE v_report text;
BEGIN
  BEGIN
    IF schema_sql IS NOT NULL THEN EXECUTE schema_sql; END IF;
    PERFORM pg_temp.el_load(data);
    SELECT string_agg(t, E'\n') INTO v_report FROM pg_temp.el_report(everything) t;
    RAISE EXCEPTION USING ERRCODE = 'EL001', MESSAGE = coalesce(v_report, 'nothing was loaded');
  EXCEPTION WHEN SQLSTATE 'EL001' THEN
    GET STACKED DIAGNOSTICS v_report = MESSAGE_TEXT;
  END;
  RETURN QUERY SELECT regexp_split_to_table(v_report, E'\n');
END $f$;

-- ---------------------------------------------------------------------------
-- The cleanup (scripts/plant-duplicates.sql): this session only
-- ---------------------------------------------------------------------------

-- Plants listed twice: the cleanup. Finds every outside id (today the EPA
-- registry id) that more than one live plant row carries, decides pair by
-- pair whether the rows are certainly one plant, merges those (plant_merge)
-- and leaves the rest where an admin will see them. Then the same for plants
-- of one company that share a spot and a name. Every decision is a line in
-- load_log (load `plant-duplicates`; `look` on the lines a person should
-- read). Nothing here knows an id: it decides on the database it meets.
--
-- The functions live in pg_temp (this session only) beside the employer
-- loader's (scripts/employers-loader.sql), whose name rules they use:
-- el_norm, el_bare, el_words, el_share, el_metres, el_merge_company.
-- scripts/ingest/README.md has the rules in words.

-- ---------------------------------------------------------------------------
-- Reading names and addresses
-- ---------------------------------------------------------------------------

-- A name's words for telling that two spellings are one name: without legal
-- endings (el_bare), apostrophes closed up, the usual abbreviations written
-- out, plurals as singulars. "A & L Labs Inc" and "A & L Laboratories
-- Incorporated" read the same.
CREATE OR REPLACE FUNCTION pg_temp.pd_canon(t text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $f$
  SELECT coalesce(array_agg(w ORDER BY ord), '{}') FROM (
    SELECT ord, CASE
      WHEN w IN ('mfg', 'mfr', 'mfrs', 'mfgr', 'manufacturer', 'manufacturers', 'manufacturing') THEN 'manufacturing'
      WHEN w IN ('ind', 'inds', 'indus', 'industry', 'industries') THEN 'industry'
      WHEN w IN ('prod', 'prods', 'product', 'products') THEN 'product'
      WHEN w IN ('lab', 'labs', 'laboratory', 'laboratories') THEN 'laboratory'
      WHEN w IN ('tech', 'techs', 'technology', 'technologies') THEN 'technology'
      WHEN w IN ('assoc', 'assocs', 'associate', 'associates', 'association') THEN 'associate'
      WHEN w IN ('intl', 'internatl', 'international') THEN 'international'
      WHEN w IN ('natl', 'national') THEN 'national'
      WHEN w IN ('bros', 'brothers') THEN 'brother'
      WHEN w IN ('sys', 'system', 'systems') THEN 'system'
      WHEN w IN ('svc', 'svcs', 'service', 'services') THEN 'service'
      WHEN w IN ('chem', 'chems', 'chemical', 'chemicals') THEN 'chemical'
      WHEN w IN ('elec', 'elect', 'electric', 'electrical') THEN 'electric'
      WHEN w IN ('eng', 'engr', 'engrg', 'engineering') THEN 'engineering'
      WHEN w IN ('equip', 'equipment') THEN 'equipment'
      WHEN w IN ('pkg', 'packaging') THEN 'packaging'
      WHEN w IN ('fdry', 'foundry', 'foundries') THEN 'foundry'
      WHEN w IN ('div', 'division') THEN 'division'
      WHEN w IN ('dept', 'department') THEN 'department'
      WHEN w IN ('plt', 'plant') THEN 'plant'
      WHEN w IN ('ave', 'avenue') THEN 'avenue'
      WHEN length(w) > 3 AND w ~ '[^s]s$' THEN left(w, -1)
      ELSE w END AS w
    FROM regexp_split_to_table(pg_temp.el_bare(translate(coalesce(t, ''), '''’`', '')), ' ') WITH ORDINALITY s(w, ord)
    WHERE w NOT IN ('', 'limited', 'cos', 'companies')
  ) x
$f$;

-- Two names that are one name written twice: the same but for legal endings
-- (the loader's rule), or the same words but for abbreviation, plural,
-- spacing and punctuation ("Ace Tank and Equipment", "Acetank & Equipment").
-- (plpgsql, like the others here that call a function with a FROM of its own:
-- a SQL function plans the functions inside it again on every call.)
CREATE OR REPLACE FUNCTION pg_temp.pd_same_name(a text, b text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $f$
DECLARE
  ba text := pg_temp.el_bare(a);
  ca text[];
  cb text[];
BEGIN
  IF ba = '' THEN RETURN false; END IF;
  IF ba = pg_temp.el_bare(b) THEN RETURN true; END IF;
  ca := pg_temp.pd_canon(a);
  cb := pg_temp.pd_canon(b);
  RETURN ca = cb OR (length(array_to_string(ca, '')) >= 4 AND array_to_string(ca, '') = array_to_string(cb, ''));
END $f$;

-- A street address for comparing: lower case, no punctuation, no post office
-- box, directions and street words in their short form, "4th" as "4".
CREATE OR REPLACE FUNCTION pg_temp.pd_street(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $f$
  SELECT coalesce(string_agg(CASE w
      WHEN 'north' THEN 'n' WHEN 'south' THEN 's' WHEN 'east' THEN 'e' WHEN 'west' THEN 'w'
      WHEN 'northeast' THEN 'ne' WHEN 'northwest' THEN 'nw' WHEN 'southeast' THEN 'se' WHEN 'southwest' THEN 'sw'
      WHEN 'street' THEN 'st' WHEN 'str' THEN 'st' WHEN 'avenue' THEN 'ave' WHEN 'av' THEN 'ave' WHEN 'road' THEN 'rd' WHEN 'drive' THEN 'dr'
      WHEN 'boulevard' THEN 'blvd' WHEN 'highway' THEN 'hwy' WHEN 'hiway' THEN 'hwy' WHEN 'hgwy' THEN 'hwy'
      WHEN 'parkway' THEN 'pkwy' WHEN 'pky' THEN 'pkwy' WHEN 'pkway' THEN 'pkwy'
      WHEN 'lane' THEN 'ln' WHEN 'court' THEN 'ct' WHEN 'place' THEN 'pl' WHEN 'circle' THEN 'cir' WHEN 'route' THEN 'rt' WHEN 'rte' THEN 'rt'
      WHEN 'freeway' THEN 'fwy' WHEN 'expressway' THEN 'expy' WHEN 'expwy' THEN 'expy' WHEN 'terrace' THEN 'ter' WHEN 'trail' THEN 'trl'
      WHEN 'county' THEN 'co' WHEN 'cnty' THEN 'co' WHEN 'fort' THEN 'ft' WHEN 'saint' THEN 'st' WHEN 'mount' THEN 'mt'
      WHEN 'building' THEN 'bldg' WHEN 'suite' THEN 'ste' WHEN 'industrial' THEN 'ind' WHEN 'indl' THEN 'ind'
      WHEN 'one' THEN '1' WHEN 'two' THEN '2' WHEN 'three' THEN '3' WHEN 'four' THEN '4' WHEN 'five' THEN '5'
      WHEN 'first' THEN '1' WHEN 'second' THEN '2' WHEN 'third' THEN '3' WHEN 'fourth' THEN '4' WHEN 'fifth' THEN '5'
      ELSE regexp_replace(w, '^([0-9]+)(st|nd|rd|th)$', '\1') END, ' ' ORDER BY ord), '')
  FROM regexp_split_to_table(regexp_replace(regexp_replace(pg_temp.el_norm(t), '\m(p o|po) box [0-9]+\M', ' ', 'g'), '\mand\M', ' ', 'g'), ' +') WITH ORDINALITY s(w, ord)
  WHERE w <> ''
$f$;

-- How far two street addresses agree: 2 strictly, 1 loosely, 0 not at all
-- (or unknown: either is empty). Strictly: the same once written one way, or
-- the same house number on a street whose name begins with the same word
-- ("152 Ipsco Road", "152 Ipsco St"; "65 Pitts Station", "65 Pitt Station"),
-- or the same words in another order. Loosely (for rows already known to be
-- close together) also: the same house number of three digits or more, or
-- the same street where one row gives no number.
CREATE OR REPLACE FUNCTION pg_temp.pd_street_match(a text, b text) RETURNS integer LANGUAGE plpgsql IMMUTABLE AS $f$
DECLARE
  sa text := pg_temp.pd_street(a);
  sb text := pg_temp.pd_street(b);
  na text;
  nb text;
  ma text[];
  mb text[];
BEGIN
  IF sa = '' OR sb = '' THEN RETURN 0; END IF;
  IF sa = sb THEN RETURN 2; END IF;
  -- The house number and the first word of the street's name that is not a direction.
  ma := regexp_match(sa, '^([0-9]+) (?:(?:n|s|e|w|ne|nw|se|sw) )?([a-z0-9]+)');
  mb := regexp_match(sb, '^([0-9]+) (?:(?:n|s|e|w|ne|nw|se|sw) )?([a-z0-9]+)');
  IF ma[1] = mb[1] AND (ma[2] = mb[2] OR (length(ma[2]) >= 4 AND length(mb[2]) >= 4
                                           AND (left(mb[2], length(ma[2])) = ma[2] OR left(ma[2], length(mb[2])) = mb[2]))) THEN
    RETURN 2;
  END IF;
  -- The same words in another order ("North Route 48", "Rte 48 N").
  IF (SELECT array_agg(w ORDER BY w) FROM regexp_split_to_table(sa, ' ') w) = (SELECT array_agg(w ORDER BY w) FROM regexp_split_to_table(sb, ' ') w) THEN
    RETURN 2;
  END IF;
  na := (regexp_match(sa, '^([0-9]+)\M'))[1];
  nb := (regexp_match(sb, '^([0-9]+)\M'))[1];
  IF na IS NOT NULL AND na = nb AND length(na) >= 3 THEN RETURN 1; END IF;
  IF (na IS NULL) <> (nb IS NULL) AND btrim(regexp_replace(sa, '^[0-9]+\M', '')) <> ''
     AND btrim(regexp_replace(sa, '^[0-9]+\M', '')) = btrim(regexp_replace(sb, '^[0-9]+\M', '')) THEN
    RETURN 1;
  END IF;
  RETURN 0;
END $f$;

-- ---------------------------------------------------------------------------
-- Is it one company
-- ---------------------------------------------------------------------------

-- Whether a company has a profile of its own: featured, a web domain, a
-- description, or people who act for it.
CREATE OR REPLACE FUNCTION pg_temp.pd_profile(c uuid) RETURNS boolean LANGUAGE sql STABLE AS $f$
  SELECT coalesce((SELECT co.featured OR co.domain IS NOT NULL OR NULLIF(btrim(co.description), '') IS NOT NULL
                          OR EXISTS (SELECT 1 FROM company_members m WHERE m.company_id = co.id)
                   FROM companies co WHERE co.id = c), false)
$f$;

-- Whether two company rows are one company, and on what evidence; null when
-- nothing recorded says so.
--   same name                       the same but for legal endings, in any letter case
--   other name                      one is known by the other's name (aliases)
--   same name, written differently  the same words but for abbreviation, plural, spacing and punctuation
--   parent                          one is recorded as part of the other
--   family                          one's name is the beginning of the other's ("Bunge", "Bunge Oils"),
--                                   unless both have a profile of their own (a joint venture
--                                   and its parent are two companies on purpose)
-- A name alone never ties a predecessor to a successor or a tenant to a
-- landlord: those stay two companies, and their plants stay for a person.
CREATE OR REPLACE FUNCTION pg_temp.pd_same_company(a uuid, b uuid) RETURNS text LANGUAGE plpgsql STABLE AS $f$
DECLARE
  x companies%ROWTYPE;
  y companies%ROWTYPE;
  bx text;
  by_ text;
BEGIN
  IF a IS NULL OR b IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO x FROM companies WHERE id = a;
  SELECT * INTO y FROM companies WHERE id = b;
  IF x.id IS NULL OR y.id IS NULL THEN RETURN NULL; END IF;
  bx := pg_temp.el_bare(x.name);
  by_ := pg_temp.el_bare(y.name);
  IF bx <> '' AND bx = by_ THEN RETURN 'same name'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(coalesce(y.aliases, '{}')) n WHERE lower(n) = lower(x.name) OR pg_temp.el_bare(n) = bx)
     OR EXISTS (SELECT 1 FROM unnest(coalesce(x.aliases, '{}')) n WHERE lower(n) = lower(y.name) OR pg_temp.el_bare(n) = by_) THEN
    RETURN 'other name';
  END IF;
  IF pg_temp.pd_same_name(x.name, y.name) THEN RETURN 'same name, written differently'; END IF;
  IF x.parent_company_id = y.id OR y.parent_company_id = x.id THEN RETURN 'parent'; END IF;
  IF ((length(bx) >= 3 AND left(by_, length(bx) + 1) = bx || ' ') OR (length(by_) >= 3 AND left(bx, length(by_) + 1) = by_ || ' '))
     AND NOT (pg_temp.pd_profile(a) AND pg_temp.pd_profile(b)) THEN
    RETURN 'family';
  END IF;
  RETURN NULL;
END $f$;

-- Whether a plant's name begins with a company's name: the company's words
-- (pd_canon: no legal endings, abbreviations written out, plurals as
-- singulars) are the plant's first words, however they are spaced ("A J
-- Knott Tool" begins "AJ KNOTT TOOL & MFG CORP"). A name under three
-- characters names nothing.
CREATE OR REPLACE FUNCTION pg_temp.pd_named_for(plant text, company text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $f$
DECLARE
  cs text := array_to_string(pg_temp.pd_canon(company), '');
  pw text[] := pg_temp.pd_canon(plant);
  v_head text := '';
  w text;
BEGIN
  IF length(cs) < 3 THEN RETURN false; END IF;
  FOREACH w IN ARRAY pw LOOP
    v_head := v_head || w;
    IF v_head = cs THEN RETURN true; END IF;
    EXIT WHEN length(v_head) >= length(cs);
  END LOOP;
  RETURN false;
END $f$;

-- The company a merged plant is filed under, of the two its rows had: the one
-- a curated row was written under; else the part before its parent; else the
-- one with a profile; else the one with more plants; else the kept row's own.
CREATE OR REPLACE FUNCTION pg_temp.pd_company_for(p_keep uuid, p_gone uuid, p_rel text) RETURNS uuid LANGUAGE sql STABLE AS $f$
  SELECT CASE
    WHEN k.curated THEN k.company_id
    WHEN p_rel = 'parent' THEN (SELECT c.id FROM companies c WHERE c.id IN (k.company_id, g.company_id) AND c.parent_company_id IN (k.company_id, g.company_id) LIMIT 1)
    ELSE (SELECT c.id FROM companies c WHERE c.id IN (k.company_id, g.company_id)
          ORDER BY pg_temp.pd_profile(c.id) DESC, (SELECT count(*) FROM factories f WHERE f.company_id = c.id) DESC, (c.id = k.company_id) DESC
          LIMIT 1)
  END
  FROM factories k, factories g WHERE k.id = p_keep AND g.id = p_gone
$f$;

-- Whether a company row has nothing of its own left: no plants, people,
-- jobs, requests, invites, companies that are part of it, web domain,
-- featured flag, description, headquarters, headcounts or citations.
CREATE OR REPLACE FUNCTION pg_temp.pd_company_bare(c uuid) RETURNS boolean LANGUAGE sql STABLE AS $f$
  SELECT NOT co.featured AND co.domain IS NULL AND co.slug IS NULL AND NULLIF(btrim(co.description), '') IS NULL AND co.headquarters_city IS NULL
    AND NOT EXISTS (SELECT 1 FROM factories x WHERE x.company_id = co.id)
    AND NOT EXISTS (SELECT 1 FROM company_members x WHERE x.company_id = co.id)
    AND NOT EXISTS (SELECT 1 FROM jobs x WHERE x.company_id = co.id)
    AND NOT EXISTS (SELECT 1 FROM invites x WHERE x.company_id = co.id)
    AND NOT EXISTS (SELECT 1 FROM company_requests x WHERE x.company_id = co.id OR x.added_company_id = co.id)
    AND NOT EXISTS (SELECT 1 FROM companies x WHERE x.parent_company_id = co.id)
    AND NOT EXISTS (SELECT 1 FROM company_state_headcounts x WHERE x.company_id = co.id)
    AND NOT EXISTS (SELECT 1 FROM external_references x WHERE x.entity_type = 'companies' AND x.entity_id = co.id)
  FROM companies co WHERE co.id = c
$f$;

-- ---------------------------------------------------------------------------
-- Is it one plant
-- ---------------------------------------------------------------------------

-- What to do with two live rows that carry one outside id. Returns
--   { decision: 'merge', rule, company, metres }   they are certainly one plant
--   { decision: 'review', reason, rule, metres }   a person decides
--   { decision: 'apart' }                          an admin already said they are two
--
-- One plant (`rule`), in this order:
--   same address   within 5 km and the street addresses agree
--   same name      within 5 km and the names are one name
--   same spot      within 100 m
--   near           within 1.5 km, and one name says only the company and the place
--   placed apart   further than 5 km (one row's coordinates are wrong): only when
--                  the street addresses agree exactly and the names do not disagree
-- Never: rows filed under two states (one is misfiled, and which is not known
-- here), or two rows both written from sources.
-- One company (`company`): the same row, or pd_same_company; or `named for`:
-- two companies nothing ties together, where the plant is certain by an
-- address or a name and both rows' names begin with the name of one of the
-- two and not the other's, unless the other has a profile and the named one
-- has none. Then the plant is that company's (`to`), and the other company
-- row is left as it is. Any other rows under two companies
-- that nothing ties together are left for a person even when the plant is
-- plainly one: which company it belongs to is not guessed.
CREATE OR REPLACE FUNCTION pg_temp.pd_verdict(p_a uuid, p_b uuid) RETURNS jsonb LANGUAGE plpgsql STABLE AS $f$
DECLARE
  a factories%ROWTYPE;
  b factories%ROWTYPE;
  v_ca text;
  v_cb text;
  d integer;
  v_drop text[];
  wa text[];
  wb text[];
  v_class integer;
  v_street integer;
  v_rule text;
  v_rel text;
  v_reason text;
  v_to uuid;
  v_left uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM plants_apart WHERE a_id = least(p_a, p_b) AND b_id = greatest(p_a, p_b)) THEN
    RETURN jsonb_build_object('decision', 'apart');
  END IF;
  SELECT * INTO a FROM factories WHERE id = p_a;
  SELECT * INTO b FROM factories WHERE id = p_b;
  SELECT name INTO v_ca FROM companies WHERE id = a.company_id;
  SELECT name INTO v_cb FROM companies WHERE id = b.company_id;
  d := CASE WHEN a.lat IS NOT NULL AND a.lng IS NOT NULL AND b.lat IS NOT NULL AND b.lng IS NOT NULL THEN pg_temp.el_metres(a.lat, a.lng, b.lat, b.lng) END;

  -- The loader's reading of two plant names: the same (0), a telling word in common (1), one says only the
  -- company and the place (2), nothing in common (3).
  v_drop := regexp_split_to_array(pg_temp.el_norm(concat_ws(' ', v_ca, v_cb, a.city, b.city, a.state, b.state)), ' ');
  IF pg_temp.pd_same_name(a.name, b.name) THEN
    v_class := 0;
  ELSE
    wa := pg_temp.el_words(a.name, v_drop);
    wb := pg_temp.el_words(b.name, v_drop);
    v_class := CASE WHEN pg_temp.el_share(wa, wb) THEN 1 WHEN cardinality(wa) = 0 OR cardinality(wb) = 0 THEN 2 ELSE 3 END;
  END IF;
  v_street := pg_temp.pd_street_match(a.address, b.address);

  v_rule := CASE
    WHEN a.state IS NOT NULL AND b.state IS NOT NULL AND a.state <> b.state THEN NULL
    WHEN a.curated AND b.curated THEN NULL
    WHEN d <= 5000 AND v_street >= 1 THEN 'same address'
    WHEN d <= 5000 AND v_class = 0 THEN 'same name'
    WHEN d <= 100 THEN 'same spot'
    WHEN d <= 1500 AND v_class = 2 THEN 'near'
    WHEN (d IS NULL OR d > 5000) AND v_street = 2 AND v_class <= 2 THEN 'placed apart'
  END;
  v_rel := CASE WHEN a.company_id IS NOT DISTINCT FROM b.company_id THEN 'one company' ELSE pg_temp.pd_same_company(a.company_id, b.company_id) END;

  -- Named for: nothing on record ties the two companies, but both rows' names begin with the name of one of them
  -- and not the other's ("AMSTED RAIL CO INC" under Amsted Rail and under Amsted Industries). The plant is that
  -- company's (the loader's own rule for a stranger's row that names a company). Only when the plant is certain by
  -- an address or a name, never when both companies have a profile or only the company that would be left has one,
  -- and never when a row written from sources stands under the other company. A recorded parent is decided above,
  -- by the parent rule.
  IF v_rel IS NULL AND v_rule IN ('same address', 'same name', 'placed apart') AND a.company_id IS NOT NULL AND b.company_id IS NOT NULL
     AND NOT (pg_temp.pd_profile(a.company_id) AND pg_temp.pd_profile(b.company_id)) THEN
    v_to := CASE
      WHEN pg_temp.pd_named_for(a.name, v_ca) AND pg_temp.pd_named_for(b.name, v_ca)
           AND NOT pg_temp.pd_named_for(a.name, v_cb) AND NOT pg_temp.pd_named_for(b.name, v_cb) THEN a.company_id
      WHEN pg_temp.pd_named_for(a.name, v_cb) AND pg_temp.pd_named_for(b.name, v_cb)
           AND NOT pg_temp.pd_named_for(a.name, v_ca) AND NOT pg_temp.pd_named_for(b.name, v_ca) THEN b.company_id
    END;
    -- Never off the page of a company with a profile onto one without: a named row that is only a fragment of the
    -- plant's name ("Becton-dickinson and" beside BD) or an unprofiled part of a profiled company stays for a person.
    v_left := CASE WHEN v_to = a.company_id THEN b.company_id ELSE a.company_id END;
    IF v_to IS NOT NULL AND NOT (a.curated AND a.company_id <> v_to) AND NOT (b.curated AND b.company_id <> v_to)
       AND NOT (pg_temp.pd_profile(v_left) AND NOT pg_temp.pd_profile(v_to)) THEN
      RETURN jsonb_build_object('decision', 'merge', 'rule', v_rule, 'company', 'named for', 'to', v_to, 'metres', d);
    END IF;
  END IF;

  IF v_rule IS NOT NULL AND v_rel IS NOT NULL THEN
    RETURN jsonb_build_object('decision', 'merge', 'rule', v_rule, 'company', v_rel, 'metres', d);
  END IF;
  v_reason := CASE
    WHEN a.state IS NOT NULL AND b.state IS NOT NULL AND a.state <> b.state THEN 'two states'
    WHEN a.curated AND b.curated THEN 'both written from sources'
    WHEN v_rule IS NULL AND (d IS NULL OR d > 5000) THEN 'far apart'
    WHEN v_rule IS NULL THEN 'names and addresses differ'
    ELSE 'two companies' END;
  RETURN jsonb_strip_nulls(jsonb_build_object('decision', 'review', 'reason', v_reason, 'rule', v_rule, 'company', v_rel, 'metres', d,
    'twoCompanies', CASE WHEN a.company_id IS DISTINCT FROM b.company_id THEN true END));
END $f$;

-- What to do with two rows of one company on one spot (coordinates equal to
-- three decimal places) that carry no id in common: merged only when the
-- names are the same plant by the loader's own rule (el_bare) and the street
-- addresses do not disagree. Two buildings of one site are two rows on purpose.
CREATE OR REPLACE FUNCTION pg_temp.pd_spot_verdict(p_a uuid, p_b uuid) RETURNS jsonb LANGUAGE plpgsql STABLE AS $f$
DECLARE
  a factories%ROWTYPE;
  b factories%ROWTYPE;
  v_reason text;
BEGIN
  IF EXISTS (SELECT 1 FROM plants_apart WHERE a_id = least(p_a, p_b) AND b_id = greatest(p_a, p_b)) THEN
    RETURN jsonb_build_object('decision', 'apart');
  END IF;
  SELECT * INTO a FROM factories WHERE id = p_a;
  SELECT * INTO b FROM factories WHERE id = p_b;
  v_reason := CASE
    WHEN pg_temp.el_bare(a.name) <> pg_temp.el_bare(b.name) THEN 'different names'
    WHEN a.state IS NOT NULL AND b.state IS NOT NULL AND a.state <> b.state THEN 'two states'
    WHEN a.curated AND b.curated THEN 'both written from sources'
    WHEN NULLIF(btrim(a.address), '') IS NOT NULL AND NULLIF(btrim(b.address), '') IS NOT NULL
         AND pg_temp.pd_street_match(a.address, b.address) = 0 THEN 'same name, different street addresses'
  END;
  IF v_reason IS NULL THEN
    RETURN jsonb_build_object('decision', 'merge', 'rule', 'same spot and name', 'company', 'one company', 'metres', pg_temp.el_metres(a.lat, a.lng, b.lat, b.lng));
  END IF;
  RETURN jsonb_build_object('decision', 'review', 'reason', v_reason);
END $f$;

-- ---------------------------------------------------------------------------
-- Doing it
-- ---------------------------------------------------------------------------

-- A plant in a few words, for a log line.
CREATE OR REPLACE FUNCTION pg_temp.pd_says(p uuid) RETURNS text LANGUAGE sql STABLE AS $f$
  SELECT format('"%s" (%s)', f.name, concat_ws('; ', (SELECT c.name FROM companies c WHERE c.id = f.company_id),
                NULLIF(concat_ws(', ', NULLIF(btrim(f.address), ''), NULLIF(btrim(f.city), ''), f.state), '')))
  FROM factories f WHERE f.id = p
$f$;

-- Merges one pair the verdict was sure of. The row kept is plant_keeps'
-- choice. Rows under two company rows that are one company end up under one
-- (pd_company_for), rows named for one of two companies under that one (the
-- verdict's `to`); a company row that is the same name and is left with
-- nothing is merged into it (the loader's company merge: its name becomes
-- another name), any other left without plants is said so. Returns the id kept.
CREATE OR REPLACE FUNCTION pg_temp.pd_merge(p_a uuid, p_b uuid, v jsonb, p_load text, p_evidence jsonb) RETURNS uuid LANGUAGE plpgsql AS $f$
DECLARE
  v_keep uuid := plant_keeps(p_a, p_b);
  v_gone uuid := CASE WHEN plant_keeps(p_a, p_b) = p_a THEN p_b ELSE p_a END;
  v_kc uuid;
  v_gc uuid;
  v_to uuid;
  v_other uuid;
  v_moved text;
  v_why text;
  v_look boolean;
  v_other_name text;
BEGIN
  SELECT company_id INTO v_kc FROM factories WHERE id = v_keep;
  SELECT company_id INTO v_gc FROM factories WHERE id = v_gone;
  v_why := CASE v->>'rule'
    WHEN 'same address' THEN 'the same street address'
    WHEN 'same name' THEN 'the same name'
    WHEN 'same spot' THEN 'the same spot'
    WHEN 'near' THEN 'close by, and one name says only the company and the place'
    WHEN 'placed apart' THEN format('the same street address and name, placed %s km apart: one row''s coordinates were wrong, check the kept row''s', round((v->>'metres')::numeric / 1000, 1))
    WHEN 'same spot and name' THEN 'the same company, spot and name'
    ELSE v->>'rule' END;
  v_look := v->>'rule' = 'placed apart';

  IF v_kc IS DISTINCT FROM v_gc THEN
    v_to := coalesce((v->>'to')::uuid, pg_temp.pd_company_for(v_keep, v_gone, v->>'company'));
    v_other := CASE WHEN v_to = v_kc THEN v_gc ELSE v_kc END;
    SELECT name INTO v_other_name FROM companies WHERE id = v_other;
    v_why := v_why || CASE WHEN v->>'company' = 'named for'
      THEN format('; both rows are named for "%s", so the plant is filed under it; nothing on record ties it to "%s", which is left as it is',
                  (SELECT name FROM companies WHERE id = v_to), v_other_name)
      ELSE format('; "%s" and "%s" are one company (%s)', (SELECT name FROM companies WHERE id = v_to), v_other_name,
                  CASE v->>'company' WHEN 'parent' THEN 'one is recorded as part of the other' WHEN 'family' THEN 'one name begins with the other' ELSE v->>'company' END) END;
    -- Worth reading when the tie between the companies is more than a legal ending.
    v_look := v_look OR v->>'company' NOT IN ('same name', 'other name');
    IF v_to <> v_kc THEN
      UPDATE factories SET company_id = v_to, updated_at = now() WHERE id = v_keep;
      UPDATE jobs SET company_id = v_to, updated_at = now() WHERE factory_id = v_keep;
      v_why := v_why || format('; the kept row moved from "%s"', v_other_name);
    END IF;
  END IF;

  PERFORM plant_merge(v_keep, v_gone, 'cleanup', NULL, p_load, v_why, v_look, NULL,
                      coalesce(p_evidence, '{}'::jsonb) || jsonb_build_object('rule', v->>'rule', 'company', v->>'company'));

  IF v_other IS NOT NULL AND NOT EXISTS (SELECT 1 FROM factories f WHERE f.company_id = v_other) THEN
    IF v->>'company' IN ('same name', 'other name', 'same name, written differently') AND pg_temp.pd_company_bare(v_other) THEN
      PERFORM pg_temp.el_merge_company(v_to, v_other);
      INSERT INTO load_log (load, kind, action, look, company, detail, entity_id, evidence)
        VALUES (p_load, 'company', 'merged', true, (SELECT name FROM companies WHERE id = v_to),
                format('"%s" had no plants left and nothing of its own, and is the same name (%s): merged in, its name kept as another name', v_other_name, v->>'company'),
                v_to, jsonb_build_object('merged', v_other, 'mergedName', v_other_name, 'company', v->>'company'));
    ELSE
      INSERT INTO load_log (load, kind, action, look, company, detail, entity_id, evidence)
        VALUES (p_load, 'company', 'left without plants', true, v_other_name,
                format('its last plant was merged into one of "%s". The row is left: %s', (SELECT name FROM companies WHERE id = v_to),
                       CASE WHEN v->>'company' IN ('parent', 'family', 'named for') THEN 'it is a different name. Merge or delete it in Admin Tools'
                            ELSE 'it has a profile, people or requests of its own. Merge it in Admin Tools' END),
                v_other, jsonb_build_object('into', v_to, 'company', v->>'company'));
    END IF;
  END IF;
  RETURN v_keep;
END $f$;

-- A pair left for a person: said once, however often the cleanup runs.
CREATE OR REPLACE FUNCTION pg_temp.pd_leave(p_a uuid, p_b uuid, v jsonb, p_load text, p_source text, p_external_id text) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  v_keep uuid := plant_keeps(p_a, p_b);
  v_other uuid := CASE WHEN plant_keeps(p_a, p_b) = p_a THEN p_b ELSE p_a END;
  v_states text;
BEGIN
  IF EXISTS (SELECT 1 FROM load_log l WHERE l.load = p_load AND l.action = 'left for review' AND l.entity_id = v_keep
             AND l.evidence->>'other' = v_other::text AND l.evidence->>'reason' = v->>'reason') THEN
    RETURN;
  END IF;
  SELECT string_agg(DISTINCT state, ' and ' ORDER BY state) INTO v_states FROM factories WHERE id IN (p_a, p_b);
  INSERT INTO load_log (load, kind, action, look, company, plant, detail, metres, source_id, entity_id, evidence)
    SELECT p_load, 'plant', 'left for review', true, (SELECT c.name FROM companies c WHERE c.id = k.company_id), k.name,
      format('%s %s: %s', pg_temp.pd_says(v_other),
        CASE WHEN p_external_id IS NULL THEN 'shares its company and spot' ELSE format('carries the same id (%s %s)', p_source, p_external_id) END,
        CASE v->>'reason'
          WHEN 'two states' THEN format('filed under two states (%s): one row is misfiled', v_states)
          WHEN 'both written from sources' THEN 'both rows were written from sources'
          WHEN 'far apart' THEN format('%s km apart, and the names or street addresses do not agree: one row''s coordinates are wrong, or they are two plants', round((v->>'metres')::numeric / 1000, 1))
          WHEN 'names and addresses differ' THEN 'the names and the street addresses differ: they may be two units of one site'
          WHEN 'two companies' THEN 'one plant under two companies that nothing on record ties together: which it belongs to is for a person to say'
          WHEN 'same name, different street addresses' THEN 'the same name at two street addresses'
          ELSE v->>'reason' END),
      (v->>'metres')::integer, p_external_id, v_keep,
      jsonb_strip_nulls(jsonb_build_object('other', v_other, 'source', p_source, 'externalId', p_external_id, 'reason', v->>'reason',
        'rule', v->>'rule', 'twoCompanies', v->'twoCompanies'))
    FROM factories k WHERE k.id = v_keep;
END $f$;

-- The whole cleanup. Safe to run again: a second run finds nothing to merge
-- and says nothing new. Returns what it did as jsonb.
CREATE OR REPLACE FUNCTION pg_temp.pd_run(p_load text DEFAULT 'plant-duplicates') RETURNS jsonb LANGUAGE plpgsql AS $f$
DECLARE
  r record;
  g record;
  v jsonb;
  v_first bigint;
  v_survivors uuid[];
  v_id uuid;
  v_s uuid;
  v_kept uuid;
  v_done boolean;
  v_named boolean;
  v_plants_before integer;
  v_companies_before integer;
  v_shared_before integer;
  v_pass integer := 0;
  v_merges integer;
  v_summary jsonb;
BEGIN
  -- "Table does not exist, skipping" is not news; the statements are long and their tables small (see el_load).
  PERFORM set_config('client_min_messages', 'warning', true);
  PERFORM set_config('jit', 'off', true);
  PERFORM set_config('el.load', p_load, true);
  SELECT coalesce(max(id), 0) INTO v_first FROM load_log;
  SELECT count(*) INTO v_plants_before FROM factories;
  SELECT count(*) INTO v_companies_before FROM companies c WHERE EXISTS (SELECT 1 FROM factories f WHERE f.company_id = c.id);

  -- 1. References to a plant that no longer exists. One that was merged away is followed to the plant it became;
  --    the rest are removed. Then an id whose first row went is no duplicate on the row that is left.
  FOR r IN
    SELECT x.id, x.source, x.external_id, x.url, x.entity_id, (SELECT f.id FROM factories f WHERE f.id = record_now('factory', x.entity_id)) AS now_id
    FROM external_references x
    WHERE x.entity_type = 'factories' AND NOT EXISTS (SELECT 1 FROM factories f WHERE f.id = x.entity_id)
    ORDER BY x.source, x.external_id, x.id
  LOOP
    IF r.now_id IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM external_references y WHERE y.entity_type = 'factories' AND y.entity_id = r.now_id AND y.source = r.source
           AND CASE WHEN r.source = 'CURATED' THEN y.url IS NOT DISTINCT FROM r.url ELSE y.external_id = r.external_id END) THEN
      UPDATE external_references SET entity_id = r.now_id,
        duplicate = duplicate OR (source <> 'CURATED' AND EXISTS (SELECT 1 FROM external_references y WHERE y.entity_type = 'factories' AND y.source = r.source
                                   AND y.external_id = r.external_id AND y.id <> r.id AND NOT y.duplicate))
        WHERE id = r.id;
      INSERT INTO load_log (load, kind, action, look, plant, detail, source_id, entity_id)
        VALUES (p_load, 'reference', 'moved', false, (SELECT name FROM factories WHERE id = r.now_id),
                format('%s pointed at a plant that was merged into this one', r.source), CASE WHEN r.source <> 'CURATED' THEN r.external_id END, r.now_id);
    ELSE
      DELETE FROM external_references WHERE id = r.id;
      INSERT INTO load_log (load, kind, action, look, detail, source_id, entity_id)
        VALUES (p_load, 'reference', 'removed', false, format('%s pointed at a plant that no longer exists', r.source),
                CASE WHEN r.source <> 'CURATED' THEN r.external_id END, r.entity_id);
    END IF;
  END LOOP;
  UPDATE external_references x SET duplicate = false
  FROM (SELECT DISTINCT ON (y.source, y.external_id) y.id
        FROM external_references y
        WHERE y.entity_type = 'factories' AND y.source <> 'CURATED' AND y.duplicate
          AND NOT EXISTS (SELECT 1 FROM external_references z WHERE z.entity_type = 'factories' AND z.source = y.source
                          AND z.external_id = y.external_id AND NOT z.duplicate)
        ORDER BY y.source, y.external_id, y.created_at, y.id) first
  WHERE x.id = first.id;

  SELECT count(*) INTO v_shared_before FROM (
    SELECT 1 FROM external_references x JOIN factories f ON f.id = x.entity_id
    WHERE x.entity_type = 'factories' AND x.source <> 'CURATED' GROUP BY x.source, x.external_id HAVING count(DISTINCT x.entity_id) > 1) s;

  -- Steps 2 and 3 are repeated until a pass merges nothing: a merge on a spot can leave a row carrying an id
  -- another row carries, and a merge on an id can move a row beside its twin. Twice is the rule; five is the limit.
  LOOP
    v_pass := v_pass + 1;
    v_merges := 0;

    -- 2. Ids carried by more than one live plant. The row plant_keeps would keep of them all is tried first; a row
    --    that is certainly the same plant as one already standing is merged into it, any other stands beside it and
    --    the pair is left for a person.
    FOR g IN
      SELECT x.source, x.external_id, array_agg(DISTINCT x.entity_id) AS plants
      FROM external_references x JOIN factories f ON f.id = x.entity_id
      WHERE x.entity_type = 'factories' AND x.source <> 'CURATED'
      GROUP BY x.source, x.external_id HAVING count(DISTINCT x.entity_id) > 1
      ORDER BY x.source, x.external_id
    LOOP
      v_kept := g.plants[1];
      FOREACH v_id IN ARRAY g.plants LOOP v_kept := plant_keeps(v_kept, v_id); END LOOP;
      v_survivors := ARRAY[v_kept];
      FOR v_id IN SELECT p FROM unnest(g.plants) p WHERE p <> v_kept ORDER BY p LOOP
        -- A row merged away earlier in this run, as one of another id's pair.
        CONTINUE WHEN NOT EXISTS (SELECT 1 FROM factories f WHERE f.id = v_id);
        v_done := false;
        FOREACH v_s IN ARRAY v_survivors LOOP
          v := pg_temp.pd_verdict(v_s, v_id);
          IF v->>'decision' = 'merge' THEN
            v_kept := pg_temp.pd_merge(v_s, v_id, v, p_load, jsonb_build_object('source', g.source, 'externalId', g.external_id, 'by', 'id'));
            v_merges := v_merges + 1;
            v_survivors := array_replace(v_survivors, v_s, v_kept);
            v_done := true;
            EXIT;
          END IF;
        END LOOP;
        IF NOT v_done THEN
          v := pg_temp.pd_verdict(v_survivors[1], v_id);
          IF v->>'decision' = 'review' THEN PERFORM pg_temp.pd_leave(v_survivors[1], v_id, v, p_load, g.source, g.external_id); END IF;
          v_survivors := v_survivors || v_id;
        END IF;
      END LOOP;
    END LOOP;

    -- 3. Plants of one company on one spot under one name, with no id in common (those were decided above).
    FOR g IN
      WITH spots AS (
        SELECT company_id, round(lat::numeric, 3) AS rlat, round(lng::numeric, 3) AS rlng
        FROM factories WHERE company_id IS NOT NULL AND lat IS NOT NULL AND lng IS NOT NULL
        GROUP BY 1, 2, 3 HAVING count(*) > 1)
      SELECT f.company_id, s.rlat, s.rlng, array_agg(f.id ORDER BY f.id) AS plants, count(DISTINCT pg_temp.el_bare(f.name)) AS names
      FROM spots s JOIN factories f ON f.company_id = s.company_id AND round(f.lat::numeric, 3) = s.rlat AND round(f.lng::numeric, 3) = s.rlng
      GROUP BY f.company_id, s.rlat, s.rlng
      ORDER BY f.company_id, s.rlat, s.rlng
    LOOP
      v_kept := g.plants[1];
      FOREACH v_id IN ARRAY g.plants LOOP v_kept := plant_keeps(v_kept, v_id); END LOOP;
      v_survivors := ARRAY[v_kept];
      v_named := false;
      FOR v_id IN SELECT p FROM unnest(g.plants) p WHERE p <> v_kept ORDER BY p LOOP
        v_done := false;
        FOREACH v_s IN ARRAY v_survivors LOOP
          -- Two rows that share an id were decided as that id's pair.
          CONTINUE WHEN EXISTS (SELECT 1 FROM external_references x JOIN external_references y ON y.source = x.source AND y.external_id = x.external_id
                                WHERE x.entity_type = 'factories' AND y.entity_type = 'factories' AND x.source <> 'CURATED' AND x.entity_id = v_s AND y.entity_id = v_id);
          v := pg_temp.pd_spot_verdict(v_s, v_id);
          IF v->>'decision' = 'merge' THEN
            v_kept := pg_temp.pd_merge(v_s, v_id, v, p_load, jsonb_build_object('by', 'spot'));
            v_merges := v_merges + 1;
            v_survivors := array_replace(v_survivors, v_s, v_kept);
            v_done := true;
            EXIT;
          ELSIF v->>'decision' = 'review' AND v->>'reason' = 'different names' THEN
            v_named := true;
          ELSIF v->>'decision' = 'review' THEN
            -- The same name on one spot, and still not certain: a person should look.
            PERFORM pg_temp.pd_leave(v_s, v_id, v, p_load, NULL, NULL);
          END IF;
        END LOOP;
        IF NOT v_done THEN v_survivors := v_survivors || v_id; END IF;
      END LOOP;
      -- Rows that stand side by side under different names are two rows on purpose (two buildings of one site): said once.
      IF v_named AND NOT EXISTS (
           SELECT 1 FROM load_log l WHERE l.load = p_load AND l.action = 'left apart' AND l.entity_id = v_survivors[1]
             AND l.evidence->'plants' = to_jsonb(v_survivors)) THEN
        INSERT INTO load_log (load, kind, action, look, company, plant, detail, entity_id, evidence)
          SELECT p_load, 'plant', 'left apart', false, (SELECT c.name FROM companies c WHERE c.id = k.company_id), k.name,
                 format('%s rows of the company stand on this spot under different names and stay separate rows: %s',
                        cardinality(v_survivors), (SELECT string_agg('"' || f.name || '"', '; ' ORDER BY f.name) FROM factories f WHERE f.id = ANY (v_survivors))),
                 k.id, jsonb_build_object('plants', to_jsonb(v_survivors), 'by', 'spot')
          FROM factories k WHERE k.id = v_survivors[1];
      END IF;
    END LOOP;

    EXIT WHEN v_merges = 0 OR v_pass >= 5;
  END LOOP;

  -- What this run did, from its own lines.
  SELECT jsonb_build_object(
    'plantsBefore', v_plants_before,
    'plantsAfter', (SELECT count(*) FROM factories),
    'listedCompaniesBefore', v_companies_before,
    'listedCompaniesAfter', (SELECT count(*) FROM companies c WHERE EXISTS (SELECT 1 FROM factories f WHERE f.company_id = c.id)),
    'idsSharedBefore', v_shared_before,
    'idsSharedAfter', (SELECT count(*) FROM (
       SELECT 1 FROM external_references x JOIN factories f ON f.id = x.entity_id
       WHERE x.entity_type = 'factories' AND x.source <> 'CURATED' GROUP BY x.source, x.external_id HAVING count(DISTINCT x.entity_id) > 1) s),
    'mergedById', count(*) FILTER (WHERE l.action = 'merged' AND l.kind = 'plant' AND l.evidence->>'by' = 'id'),
    'mergedBySpot', count(*) FILTER (WHERE l.action = 'merged' AND l.kind = 'plant' AND l.evidence->>'by' = 'spot'),
    'leftForReview', count(*) FILTER (WHERE l.action = 'left for review'),
    'passes', v_pass,
    'companiesMerged', count(*) FILTER (WHERE l.kind = 'company' AND l.action = 'merged'),
    'companiesLeftWithoutPlants', count(*) FILTER (WHERE l.kind = 'company' AND l.action = 'left without plants'),
    'referencesRemoved', count(*) FILTER (WHERE l.kind = 'reference' AND l.action = 'removed'),
    'referencesMoved', count(*) FILTER (WHERE l.kind = 'reference' AND l.action = 'moved'),
    'byRule', coalesce((SELECT jsonb_object_agg(rule, n) FROM (SELECT m.evidence->>'rule' AS rule, count(*) AS n FROM load_log m
                         WHERE m.id > v_first AND m.load = p_load AND m.kind = 'plant' AND m.action = 'merged' GROUP BY 1) t), '{}'::jsonb),
    'byCompany', coalesce((SELECT jsonb_object_agg(company, n) FROM (SELECT m.evidence->>'company' AS company, count(*) AS n FROM load_log m
                         WHERE m.id > v_first AND m.load = p_load AND m.kind = 'plant' AND m.action = 'merged' GROUP BY 1) t), '{}'::jsonb),
    'byReason', coalesce((SELECT jsonb_object_agg(reason, n) FROM (SELECT m.evidence->>'reason' AS reason, count(*) AS n FROM load_log m
                         WHERE m.id > v_first AND m.load = p_load AND m.action = 'left for review' GROUP BY 1) t), '{}'::jsonb))
    INTO v_summary
  FROM load_log l WHERE l.id > v_first AND l.load = p_load;

  -- The summary is a line of its own only when the run did something.
  IF EXISTS (SELECT 1 FROM load_log l WHERE l.id > v_first AND l.load = p_load) THEN
    INSERT INTO load_log (load, kind, action, look, detail, evidence)
      VALUES (p_load, 'run', 'summary', true,
              format('%s plants before, %s after. %s ids were carried by more than one plant; %s pairs merged on an id, %s on a spot and a name; %s pairs left for a person; %s company rows merged; %s references to plants that no longer exist removed.',
                     v_summary->>'plantsBefore', v_summary->>'plantsAfter', v_summary->>'idsSharedBefore', v_summary->>'mergedById', v_summary->>'mergedBySpot',
                     v_summary->>'leftForReview', v_summary->>'companiesMerged', v_summary->>'referencesRemoved'),
              v_summary);
  END IF;
  RETURN v_summary;
END $f$;

-- A rehearsal: runs the whole cleanup, reads what it decided, then undoes it
-- (the employer loader's way: the work is done in a block that ends by
-- raising an error, and the report rides out in the error). `schema_sql` is
-- scripts/plant-merge.sql, for a copy that does not have it yet. With
-- `everything` every line is returned, not only the ones marked for a look.
CREATE OR REPLACE FUNCTION pg_temp.pd_rehearse(schema_sql text, everything boolean) RETURNS SETOF text LANGUAGE plpgsql AS $f$
DECLARE
  v_report text;
  v_first bigint;
  v_summary jsonb;
BEGIN
  BEGIN
    IF schema_sql IS NOT NULL THEN EXECUTE schema_sql; END IF;
    SELECT coalesce(max(id), 0) INTO v_first FROM load_log;
    v_summary := pg_temp.pd_run('plant-duplicates');
    SELECT jsonb_pretty(v_summary) || E'\n' || coalesce(string_agg(
             format('%s%s %s | %s%s%s', CASE WHEN l.look THEN '' ELSE '  ' END, l.kind, l.action, coalesce(l.company, ''),
                    coalesce(' / ' || l.plant, ''), coalesce(' | ' || l.detail, '')), E'\n' ORDER BY l.id), '')
      INTO v_report
    FROM load_log l WHERE l.id > v_first AND l.load = 'plant-duplicates' AND (l.look OR everything) AND l.action <> 'summary';
    RAISE EXCEPTION USING ERRCODE = 'PD001', MESSAGE = coalesce(v_report, 'nothing to do');
  EXCEPTION WHEN SQLSTATE 'PD001' THEN
    GET STACKED DIAGNOSTICS v_report = MESSAGE_TEXT;
  END;
  RETURN QUERY SELECT regexp_split_to_table(v_report, E'\n');
END $f$;

SELECT pg_temp.pd_run('plant-duplicates');
